//#region 🔖️ArtifactChannel
/// 🔌️ Real `crate::actions::ArtifactChannel` implementation — the seam `P6-actions-policy`'s
/// `ActionAdapter` drives (`🔀️dispatch/🦀️.rs`'s own module doc: "is P7's job when it
/// implements `ArtifactChannel` for real"). `ReadHistory` is driven for REAL over
/// `GuestRuntime::execute_turn` (one retained command page per turn, scan `TurnResult.effects` for
/// `Effect::Respond{req, result}` where `req.0 == seq`, decode `RequestOutcome::Ok` as a real
/// `store::AppFrame::HistorySnapshot` — exactly the "real body" `🏃️run/🦀️.rs`'s own
/// `WasmtimeNodeHost::exchange` doc comment describes and does not itself build). The mutation
/// variants (`PureCommand`/`TransactionPrepare`/`Commit`/`Rollback`/`Undo`/`Redo`) need a real
/// `manifest::ActionInvocation{address: ActionAddress{plugin_id, app_id, mode_id, window_kind_id,
/// window_instance_id, action_id}, arguments}` — every one of those five address fields beyond
/// `plugin_id`/`app_id` is normally supplied by a LIVE window/mode the headless gateway has none of;
/// inventing placeholder values for them is a real design decision (what does a headless agent's
/// "window"/"mode" even mean) this packet is not positioned to make unilaterally in the time
/// available, so — same honesty rule as `🏃️run`'s own `run_transaction`/`undo_transaction_group` —
/// these return a well-formed, typed `"channel.not-wired"` `Fault` naming exactly what is missing,
/// never a fabricated result.
#[cfg(not(target_arch = "wasm32"))]
pub struct PluginArtifactChannel {
    /// 🐎️ The process-wide compiled runtime ([`shared_plugin_runtime`]), held as the `GuestRuntimes`
    /// enum rather than a bare `WasmtimeRuntime` because the inference lane's
    /// `PluginInstanceHandle` takes exactly that `Arc` — and it MUST be the same one: a
    /// `wasmtime::Component` belongs to the `Engine` that compiled it, so a second runtime could not
    /// instantiate `compiled` at all.
    runtime: Arc<GuestRuntimes>,
    compiled: semio_framework_plugin_host::CompiledHandle,
    /// 🔌️ The plugin this channel drives. It is the id alone, never a registry ROW: the row names a
    /// repo path this channel has no use for, and a hub-authorized component has no repo path at all.
    plugin_id: String,
    descriptor: semio_framework::PackageDescriptor,
    app_ref: semio_framework::AppRef,
    actor_label: String,
    instances: HashMap<u32, semio_framework_plugin_host::GuestInstance>,
    pending_exchanges: PendingExchangeRegistry<1>,
    pending_command_closes: semio_framework::kernel::CommandDriverRegistry<1>,
    rejected_command_builds: semio_framework::kernel::RejectedCommandBuildRegistry<1>,
    next_seq: u64,
    /// 🗿️ The artifact id this channel's ONE live guest session document is, when the owning
    /// workspace has bound exactly one artifact to this plugin. Every `RevisionStamp` this channel
    /// answers names it.
    ///
    /// 🐛️ Before ticket 26/09/18 slice M8 the stamp carried `entry.plugin_id`, so the headless
    /// lane's `expectedRevision` named `"note"` while `artifact_create`/`artifact_snapshot` named
    /// `"…-typed"` — two ids for one document, and `artifact_snapshot(revisionAfter.artifactId)`
    /// answered `no such artifact: note` (`📓️ce1-client-e2e-pinning-and-puzzle-bound.md` §8 gap 4).
    session_artifact_id: Option<String>,
    /// 📥️ Per guest instance, the artifact id whose canonical pair that guest's session document
    /// currently IS — see [`Self::load_session_document`]. Empty for a guest still sitting on the
    /// plugin's own genesis document, which is every folder-lane guest and was, before ticket
    /// 26/09/18 slice M10, every hub-lane one as well.
    session_documents: HashMap<u32, String>,
    /// 🧵️ Document-backbone messages this guest published and this channel has not handed on yet —
    /// the `Effect::SendMessage { target: Backbone { uri } }` payloads addressed at this channel's
    /// own actor uri. They used to be dropped on the floor: `exchange_one_turn` named every effect
    /// for diagnostics and admitted only the `Shell{instance}` reply lane, so a committed
    /// transaction's envelopes — the ONE thing that has to leave the process for anyone else to see
    /// the edit — went nowhere at all.
    backbone_egress: Vec<Vec<u8>>,
    /// 🧵️ The instances whose document backbone this channel has bound — see
    /// [`Self::ensure_document_backbone`]. Cleared per instance by [`Self::discard_instance`],
    /// because a guest that was thrown away holds no binding.
    backbone_bindings: std::collections::BTreeSet<u32>,
    /// 💡️ Lazily opened on the FIRST `AppCommand::Infer` — a second guest activation of the same
    /// component, dedicated to the cold `semio.infer` job lane. Deliberately separate from
    /// `instances` above: `PluginInstanceHandle` takes ownership of its `GuestInstance` and drives
    /// `start-job`/`step-job` against it from a worker pool, which the retained command-page loop
    /// `exchange_one_real` runs on the same instance cannot share.
    inference: Option<PluginInferenceRoute>,
}

/// 💡️ One plugin's real `semio.infer` route — the SAME `ArtifactInferenceRouter` +
/// `PluginInstanceHandle` pair `🏃️run/🦀️.rs`'s own `load_runtime_recursive` builds, constructed here
/// from the committed descriptor instead of from a live `run` process. The router owns the handle
/// (which owns the `Arc<GuestRuntimes>` and the `GuestInstance`), so this struct holds only it.
#[cfg(not(target_arch = "wasm32"))]
struct PluginInferenceRoute {
    router: semio_framework_plugin_host::ArtifactInferenceRouter,
}

#[cfg(not(target_arch = "wasm32"))]
struct PendingExchange {
    instance: u32,
    seq: u64,
    response: PendingResponsePage,
    /// 🧾️ The guest's own reason for a faulted ingress, kept from the turn that reported it until
    /// the bounded cleanup that follows reaches its terminal and can answer the caller with it.
    ingress_fault: Option<String>,
}

#[cfg(not(target_arch = "wasm32"))]
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum PendingResponseFault {
    Oversized,
    Duplicate,
}

/// 📬️ One command's answer, as it arrives: the guest's own encoded `AppFrame` bytes off the
/// `Shell{instance}` message lane.
///
/// 🧭️ This used to hold a single [`semio_framework::kernel::FixedCommandPage`], because the answer
/// was read off `Effect::Respond` and a `RequestOutcome`'s bytes are one page. An `AppFrame` is not:
/// `ReadDocument` answers a whole `Document{pack, spr}`, which for any real artifact is far past
/// 4 KiB, so that ceiling would have refused every genuine answer the moment the lane was read
/// correctly. The ceiling that does apply is the declared one for a single host↔guest answer,
/// [`semio_framework::kernel::COMMAND_MAXIMUM_BYTES`] — 8 MiB — and it is still a hard bound, so an
/// unbounded guest answer is a typed fault rather than an allocation.
#[cfg(not(target_arch = "wasm32"))]
enum PendingResponsePage {
    Empty,
    Frame { bytes: Vec<u8>, duplicate: bool },
    /// 🏁️ The command settled and the guest published no frame naming it — the same reading the
    /// React host takes (`🔌️PluginRuntime/🟦️.tsx`'s `commandIngressNeedsReplyStampV1`, which stamps
    /// `AppFrame::Done{in_reply_to}` on exactly this shape so a caller never waits on an answer a
    /// completed command was never going to publish). A caller that needs a real frame reports the
    /// `Done` as the unexpected variant it is; a caller whose verb genuinely answers `Done`
    /// (`LoadDocument`, `TransactionUndo`/`Redo`) reads its own success.
    Stamped,
    Fault(PendingResponseFault),
}

#[cfg(not(target_arch = "wasm32"))]
impl PendingResponsePage {
    fn admit_frame(&mut self, bytes: &[u8]) {
        match self {
            Self::Empty => {
                *self = if bytes.len() > semio_framework::kernel::COMMAND_MAXIMUM_BYTES { Self::Fault(PendingResponseFault::Oversized) } else { Self::Frame { bytes: bytes.to_vec(), duplicate: false } };
            }
            Self::Frame { duplicate, .. } => *duplicate = true,
            Self::Stamped | Self::Fault(_) => *self = Self::Fault(PendingResponseFault::Duplicate),
        }
    }

    fn stamp_settled(&mut self) {
        if matches!(self, Self::Empty) {
            *self = Self::Stamped;
        }
    }

    /// 🏁️ Whether a real answer is already held — the test that tells a redundant `AppFrame::Done`
    /// stamp apart from a genuine second answer (see [`RoutingArtifactChannel`]'s sibling
    /// `admit_reply_frame`).
    fn holds_frame(&self) -> bool {
        matches!(self, Self::Frame { .. })
    }

    fn take(&mut self, seq: u64) -> Result<store::AppFrame, Fault> {
        match std::mem::replace(self, Self::Empty) {
            Self::Empty => Err(PluginArtifactChannel::not_wired("execute_turn", format!("no AppFrame answering seq {seq} before terminal acknowledgement"))),
            Self::Frame { duplicate: true, .. } => Err(PluginArtifactChannel::not_wired("AppFrame response", format!("the guest published more than one frame answering seq {seq}"))),
            Self::Frame { bytes, duplicate: false } => ::semio_framework_async::poll::resolve_ready(store::decode_app_frame(&bytes)).map_err(|error| PluginArtifactChannel::not_wired("decoding AppFrame", error)),
            Self::Stamped => Ok(store::AppFrame::Done { in_reply_to: seq }),
            Self::Fault(PendingResponseFault::Oversized) => Err(PluginArtifactChannel::not_wired("AppFrame response", format!("the guest's answer exceeds the declared {}-byte host answer ceiling", semio_framework::kernel::COMMAND_MAXIMUM_BYTES))),
            Self::Fault(PendingResponseFault::Duplicate) => Err(PluginArtifactChannel::not_wired("AppFrame response", format!("the guest published more than one frame answering seq {seq}"))),
        }
    }

    /// 🧹️ A frame larger than one retirement grant is released a grant at a time, so a
    /// faulted command's cleanup stays bounded however big the answer the guest had queued.
    fn close_step(&mut self, maximum_bytes: usize) -> (bool, usize) {
        let released = match self {
            Self::Frame { bytes, .. } if bytes.len() <= maximum_bytes => bytes.len(),
            Self::Frame { bytes, .. } => {
                let remaining = bytes.len() - maximum_bytes;
                bytes.truncate(remaining);
                return (false, maximum_bytes);
            }
            Self::Empty | Self::Stamped | Self::Fault(_) => 0,
        };
        *self = Self::Empty;
        (true, released)
    }

    fn terminal_is_empty(&self) -> bool {
        matches!(self, Self::Empty)
    }
}

/// 🪟️ What a HEADLESS agent's transaction carries of one previewed verb: its document operations and owned children, never
/// its config or draft lanes — those are the view state (a selection, a viewport, a mode) of a shell the agent does not
/// have, and the real wire `TransactionPrepare` has no lane for them (coordinator decision, ticket 26/09/23 session 14c: a
/// headless agent edits DOCUMENTS). Beside a document change they are omitted and the preview says so
/// ([`VIEW_STATE_OMITTED_WARNING`]); a verb whose whole effect is view state is refused
/// [`crate::actions::AGENT_LANE_UNCARRIED_FAULT_CODE`] at prepare — it runs only from the shell — instead of failing at
/// invoke with "no wire representation" (live hub coverage on 7800/p33: procedural's add/rename/removeGeneration publish
/// `SetSelectedGeneration` beside their document op).
#[cfg(not(target_arch = "wasm32"))]
fn headless_agent_ops(capability_id: &str, ops: PreparedOps) -> Result<(PreparedOps, Vec<String>), Fault> {
    let view_lanes = [("config", !ops.config.is_empty()), ("draft", !ops.draft.is_empty())].into_iter().filter_map(|(lane, held)| held.then_some(lane)).collect::<Vec<_>>();
    if view_lanes.is_empty() {
        return Ok((ops, Vec::new()));
    }
    if ops.document.is_empty() && ops.children.is_empty() {
        return Err(Fault {
            code: crate::actions::AGENT_LANE_UNCARRIED_FAULT_CODE.to_string(),
            message: format!("action '{capability_id}' changes only {} view state, which a headless agent's transaction cannot carry; it runs only from the shell", view_lanes.join(" and ")),
        });
    }
    Ok((PreparedOps { config: Vec::new(), draft: Vec::new(), ..ops }, vec![VIEW_STATE_OMITTED_WARNING.to_string()]))
}

/// 🪟️ The preview warning of a verb whose config/draft view state a headless agent's transaction leaves in the shell.
#[cfg(not(target_arch = "wasm32"))]
pub const VIEW_STATE_OMITTED_WARNING: &str = "view-state-omitted: the action's config/draft view state (a selection, a viewport, a mode) stays in the shell; this transaction commits its document operations only";

/// 🧹️ Begins closing the exchange an ABANDONED command left on `instance` — a pending exchange whose seq is not `seq`'s —
/// so the bounded teardown in `exchange_one_turn` retires it before the next command on the instance is admitted.
#[cfg(not(target_arch = "wasm32"))]
fn begin_closing_abandoned_exchange(pending_exchanges: &PendingExchangeRegistry<1>, closes: &mut semio_framework::kernel::CommandDriverRegistry<1>, instance: u32, seq: u64) -> Result<(), Fault> {
    let Some(abandoned) = pending_exchanges.get(instance).map(|pending| pending.seq).filter(|pending_seq| *pending_seq != seq) else { return Ok(()) };
    if closes.is_active(u64::from(instance), abandoned) {
        closes.begin_close(u64::from(instance), abandoned).map_err(|fault| Fault { code: "channel.not-wired".to_string(), message: format!("abandoned command owner: {}: {}", fault.code.0, fault.message) })?;
    }
    Ok(())
}

#[cfg(not(target_arch = "wasm32"))]
struct PendingExchangeRegistry<const CAPACITY: usize> {
    slots: [Option<PendingExchange>; CAPACITY],
}

#[cfg(not(target_arch = "wasm32"))]
impl<const CAPACITY: usize> PendingExchangeRegistry<CAPACITY> {
    fn new() -> Self {
        Self { slots: std::array::from_fn(|_| None) }
    }

    fn can_insert(&self, instance: u32) -> bool {
        self.slots[instance as usize % CAPACITY].is_none()
    }

    fn insert_admitted(&mut self, pending: PendingExchange) {
        let index = pending.instance as usize % CAPACITY;
        assert!(self.slots[index].is_none(), "fixed pending-exchange admission changed before insert");
        self.slots[index] = Some(pending);
    }

    fn get_mut(&mut self, instance: u32) -> Option<&mut PendingExchange> {
        self.slots[instance as usize % CAPACITY].as_mut().filter(|pending| pending.instance == instance)
    }

    fn get(&self, instance: u32) -> Option<&PendingExchange> {
        self.slots[instance as usize % CAPACITY].as_ref().filter(|pending| pending.instance == instance)
    }

    fn remove(&mut self, instance: u32) -> Option<PendingExchange> {
        let index = instance as usize % CAPACITY;
        if self.slots[index].as_ref().is_some_and(|pending| pending.instance == instance) {
            self.slots[index].take()
        } else {
            None
        }
    }

    fn close_response_step(&mut self, instance: u32, maximum_bytes: usize) -> (bool, usize) {
        self.get_mut(instance).map_or((true, 0), |pending| pending.response.close_step(maximum_bytes))
    }
}

#[cfg(not(target_arch = "wasm32"))]
/// 🔢️ The actor ordinal the inference-only activation uses. Distinct from every `ensure_instance`
/// ordinal (those are `instance + 1`, i.e. `1..=u16::MAX - 1`) so an inference guest can never
/// collide with a command-lane guest of the same plugin.
#[cfg(not(target_arch = "wasm32"))]
const INFERENCE_ACTOR_ORDINAL: u16 = u16::MAX;

/// ⏱️ The finite allocation/recursion limits every `AppCommand::Infer` carries. Work units come from
/// the caller (clamped to at least one); these two are host policy, not caller input, because an
/// agent must not be able to widen a guest's memory or dependency-recursion envelope.
#[cfg(not(target_arch = "wasm32"))]
const INFERENCE_ALLOCATION_BYTES: u64 = 1 << 20;
#[cfg(not(target_arch = "wasm32"))]
const INFERENCE_RECURSION_DEPTH: u32 = 4;

/// 💡️ The budget the INFERENCE lane's own guest runs under. An 8 ms interpreter slice
/// exists to keep a UI frame responsive; the inference lane has no frame to keep — it activates its
/// own guest (`INFERENCE_ACTOR_ORDINAL`) and `ArtifactInferenceRouter` drives the cold `semio.infer`
/// job to completion inside ONE call this crate cannot resume from the outside, so an 8 ms epoch
/// deadline made every real declared inference answer `epoch deadline exceeded` (measured
/// 2026-09-19 against an installed owner service). Still a hard ceiling:
/// a runaway guest is stopped, just on a headless job's own time scale. `fuel` is disarmed for the
/// same reason the two budgets below disarm it: under the compiled runtime a fuel yield is as
/// unresumable as an epoch cut, so the time ceiling is the only one worth arming.
#[cfg(not(target_arch = "wasm32"))]
fn headless_inference_budget() -> semio_framework::kernel::Budget {
    semio_framework::kernel::Budget { fuel: u64::MAX, deadline_ms: 30_000, max_effects: 4096, max_patch_bytes: 1 << 24, max_frames: 4096 }
}

/// 🎬️ The budget a COLD OPEN turn runs under. A ceiling, not a slice: under the compiled runtime a
/// turn is atomic — an epoch deadline cut leaves the component instance mid-call and every later
/// call answers `cannot enter component instance` — so this number is the point at which the guest
/// is declared wedged and its instance is thrown away, never a quantum the host resumes from. 60 s
/// is far above what the os dev host needs to boot the same components (~20 plugins in seconds) and
/// far below the MCP client's own 240 s per-call budget, so a wedged open still answers the agent.
///
/// ⛽️ `fuel` is deliberately disarmed. Under the JIT a fuel yield is exactly as unresumable as an
/// epoch cut, so arming both would only add a second, harder-to-read way to say "wedged"; the time
/// ceiling is the one an agent and an operator can both reason about. `🔬️owned-instance-open`'s
/// `wasmtime_runtime_instance_open_settles_against_a_real_plugin_component` opens a real component
/// under exactly this shape.
#[cfg(not(target_arch = "wasm32"))]
fn headless_open_budget() -> semio_framework::kernel::Budget {
    semio_framework::kernel::Budget { fuel: u64::MAX, deadline_ms: 60_000, max_effects: 4096, max_patch_bytes: 1 << 24, max_frames: 4096 }
}

/// 📨️ The ceiling ONE `AppCommand` page turn runs under — same reasoning as
/// [`headless_open_budget`], on the scale of a bounded unit of work rather than a whole app
/// assembly. A command still takes several turns (one retained page per turn, then the guest's
/// terminal acknowledgement), but each of those turns runs to completion; the loop that drives them
/// is [`COMMAND_RESUME_WALL_BUDGET`]'s, and reaching THIS ceiling means one turn wedged.
#[cfg(not(target_arch = "wasm32"))]
fn headless_command_budget() -> semio_framework::kernel::Budget {
    semio_framework::kernel::Budget { fuel: u64::MAX, deadline_ms: 5_000, max_effects: 4096, max_patch_bytes: 1 << 24, max_frames: 4096 }
}

/// ⏱️ How long the page loop for ONE `AppCommand` may keep taking turns before it reports the stall
/// to the caller. A wedged guest must still surface as a bounded, honest `budget.exceeded` rather
/// than a hung MCP tool call, so this is a wall clock, not an attempt count. Every turn inside it
/// completes, so this bounds the NUMBER of pages and host-side cleanup steps a command may need,
/// not the duration of any single guest call.
#[cfg(not(target_arch = "wasm32"))]
const COMMAND_RESUME_WALL_BUDGET: std::time::Duration = std::time::Duration::from_secs(60);

/// ⏱️ How long a cold open may keep taking turns. Larger than [`headless_open_budget`] because an
/// open is at least two turns — the `Event::InstanceOpen` itself and the `InstanceLifecycleAck` for
/// the receipt it publishes — and well under the MCP client's own 240 s per-call budget, so a guest
/// that cannot come up is reported as a bounded `budget.exceeded` instead of killing the tool call.
#[cfg(not(target_arch = "wasm32"))]
const INSTANCE_OPEN_WALL_BUDGET: std::time::Duration = std::time::Duration::from_secs(150);

/// 🐎️ ONE compiled runtime for this process, built on first use. `build_shared_engine`'s own
/// contract is one `Engine` per process (a pooling allocator reservation and a 1 ms epoch ticker
/// each), and a `wasmtime::Component` may only be instantiated by the `Engine` that compiled it — so
/// every `PluginArtifactChannel`, and every inference route they open, share this one.
///
/// 🧊️ Held as the `GuestRuntimes` enum because `PluginInstanceHandle::new` takes an
/// `Arc<GuestRuntimes>`; the enum delegates every `GuestRuntime` method to the wasmtime arm with no
/// indirection beyond a match.
///
/// ⛽️ Unmetered: every budget this gateway arms disarms fuel (`u64::MAX`) and bounds a guest call
/// by its epoch deadline, so metering bought nothing here but instrumented every guest block — see
/// [`SharedEngineConfig::fuel_metering`] for the measurement.
///
/// 🧯️ A failed engine build is cached as a `String` rather than retried per call: it fails for
/// reasons that do not change inside a process (no virtual address space, an unusable cache root),
/// and retrying it on every tool call would turn one honest refusal into a stall.
#[cfg(not(target_arch = "wasm32"))]
fn shared_plugin_runtime() -> Result<Arc<GuestRuntimes>, GatewayError> {
    static RUNTIME: std::sync::OnceLock<Result<Arc<GuestRuntimes>, String>> = std::sync::OnceLock::new();
    RUNTIME
        .get_or_init(|| semio_framework_async::block_on(WasmtimeRuntime::new(SharedEngineConfig { fuel_metering: false, ..SharedEngineConfig::default() })).map(|runtime| Arc::new(GuestRuntimes::from(runtime))).map_err(|error| error.to_string()))
        .clone()
        .map_err(|error| GatewayError::new(GatewayErrorCode::Internal, format!("building the shared plugin engine: {error}")))
}

/// 🧩️ ONE compiled component per staged build, for the life of the process, keyed by the
/// component's own content hash so a rebuilt plugin is a different entry rather than a stale one.
///
/// 🪦️ This is not only about not compiling twice. A `wasmtime::Component` owns a mapped code image
/// — 136 MB for `🖍️draw`'s `wasm-dev` build — and releasing the LAST `Arc` to one runs
/// `CodeMemory`'s `UnwindRegistration::drop`, i.e. a `__deregister_frame` walk over every frame in
/// that image. Measured 2026-09-20 on a calm machine: the open itself is 34 ms and the drop of the
/// component behind it pins a thread at 100 % for minutes, which is what made the gateway's first
/// plugin tool call answer nothing at all inside the MCP client's 240 s budget — the work was in
/// tearing the component DOWN after a successful call, not in bringing it up. Holding the handle
/// here keeps the refcount above zero, so a channel's own drop releases its `Store` and stops.
#[cfg(not(target_arch = "wasm32"))]
fn compiled_components() -> &'static Mutex<HashMap<[u8; 32], semio_framework_plugin_host::CompiledHandle>> {
    static COMPILED: OnceLock<Mutex<HashMap<[u8; 32], semio_framework_plugin_host::CompiledHandle>>> = OnceLock::new();
    COMPILED.get_or_init(|| Mutex::new(HashMap::new()))
}

/// 🪪️ What a staged component file IS without reading it: its path, length and modification time.
/// A rebuild rewrites the file, so it changes the identity and is read and hashed again.
#[cfg(not(target_arch = "wasm32"))]
#[derive(Clone, PartialEq, Eq, Hash)]
struct ComponentFileIdentity {
    path: PathBuf,
    length: u64,
    modified_ns: u128,
}

/// 🔏️ The content hash of every staged component file already read, by file identity — held in this
/// process and persisted beside the compiled-code cache, so a staged build is read and hashed once
/// per build rather than once per process.
///
/// ⏱️ Every channel open used to read the whole component and hash it before it could ask the
/// compiled cache anything: measured 2026-09-24 (ticket 26/09/23 slice G6) the 125 MB `🀄️wfc`
/// build took 8.5–11.5 s to hash in a dev host, once for `artifact_create` and again for the first
/// `inference_run` binding of the same session, while the compiled-code lookup behind it took 0.3 s.
#[cfg(not(target_arch = "wasm32"))]
fn component_file_hashes() -> &'static Mutex<HashMap<ComponentFileIdentity, [u8; 32]>> {
    static HASHES: OnceLock<Mutex<HashMap<ComponentFileIdentity, [u8; 32]>>> = OnceLock::new();
    HASHES.get_or_init(|| Mutex::new(HashMap::new()))
}

#[cfg(not(target_arch = "wasm32"))]
impl ComponentFileIdentity {
    /// 🗂️ Where this identity's content hash is persisted: one 32-byte file under the compiled-code
    /// cache root, named by the digest of the identity itself.
    fn persisted_path(&self) -> PathBuf {
        let key = format!("semio.component-file-identity/v1\0{}\0{}\0{}", self.path.display(), self.length, self.modified_ns);
        semio_framework_async::block_on(semio_framework_plugin_host::default_compiled_cache_root()).join("component-identities").join(framework_hash::hash_bytes(key.as_bytes()))
    }

    fn known_hash(&self) -> Option<[u8; 32]> {
        if let Some(hash) = component_file_hashes().lock().unwrap_or_else(std::sync::PoisonError::into_inner).get(self).copied() {
            return Some(hash);
        }
        let hash: [u8; 32] = std::fs::read(self.persisted_path()).ok()?.try_into().ok()?;
        component_file_hashes().lock().unwrap_or_else(std::sync::PoisonError::into_inner).insert(self.clone(), hash);
        Some(hash)
    }

    fn remember(&self, hash: [u8; 32]) {
        component_file_hashes().lock().unwrap_or_else(std::sync::PoisonError::into_inner).insert(self.clone(), hash);
        let path = self.persisted_path();
        if let Some(parent) = path.parent() {
            let _ = std::fs::create_dir_all(parent);
        }
        let _ = std::fs::write(path, hash);
    }
}

/// 🧩️ Where a component's bytes come from: a staged file this process may already know, or bytes a
/// caller already holds (a hub-authorized execution target).
#[cfg(not(target_arch = "wasm32"))]
enum ComponentBytes<'a> {
    File(&'a Path),
    Held(&'a [u8]),
}

/// 📏️ How much of a component one hashing step covers before it reports progress and checks cancel.
#[cfg(not(target_arch = "wasm32"))]
const COMPONENT_HASH_CHUNK_BYTES: usize = 4 << 20;

#[cfg(not(target_arch = "wasm32"))]
fn activation_fault(fault: Fault) -> GatewayError {
    if fault.code == ACTIVATION_CANCELLED_FAULT_CODE {
        return GatewayError::new(GatewayErrorCode::Cancelled, fault.message);
    }
    GatewayError::new(GatewayErrorCode::Internal, fault.message)
}

/// 🔏️ `bytes`' own 32-byte content digest, one chunk per progress report and cancel check.
///
/// 🔏️ The component's OWN digest, not `hash_bytes`' 64-char HEX STRING: that string's `into_bytes()`
/// is 64 long, so `try_into::<[u8; 32]>()` always failed and every plugin in this process took a
/// `[0u8; 32]` fallback. `WasmtimeRuntime::compile` keys its on-disk `.cwasm` cache on it, so the
/// placeholder made every plugin collide on ONE cache entry and replay whichever component compiled
/// first. Measured 2026-09-20: a single 130 MB `0000…0000.cwasm`.
#[cfg(not(target_arch = "wasm32"))]
fn scoped_component_hash(bytes: &[u8], scope: &ActivationScope) -> Result<[u8; 32], GatewayError> {
    let mut hasher = framework_hash::Hasher::new();
    let mut hashed = 0usize;
    for chunk in bytes.chunks(COMPONENT_HASH_CHUNK_BYTES) {
        hasher.update(chunk);
        hashed += chunk.len();
        scope.advance(ActivationPhase::HashingComponent, hashed as f64 / bytes.len().max(1) as f64).map_err(activation_fault)?;
    }
    Ok(*hasher.finalize().as_bytes())
}

#[cfg(not(target_arch = "wasm32"))]
fn read_component(path: &Path, scope: &ActivationScope) -> Result<Vec<u8>, GatewayError> {
    scope.enter(ActivationPhase::ReadingComponent).map_err(activation_fault)?;
    std::fs::read(path).map_err(|error| GatewayError::new(GatewayErrorCode::Internal, format!("reading {}: {error}", path.display())))
}

/// 🧩️ The process's compiled handle for one component, reporting each phase it actually runs to
/// `scope`. A staged file already hashed in this process is neither read nor hashed again; compiled
/// code already in this process or on disk is loaded, never compiled again, and the component is
/// read only when it must be compiled. A cold compile runs in an isolated worker process shared by
/// every requester of the same content hash ([`CompileFlight`]), so a cancel detaches this requester
/// at once and the last requester's cancel kills the compile.
#[cfg(not(target_arch = "wasm32"))]
fn scoped_compiled_component(runtime: &GuestRuntimes, plugin_id: &str, component: ComponentBytes<'_>, scope: &ActivationScope) -> Result<semio_framework_plugin_host::CompiledHandle, GatewayError> {
    let (package_hash, mut bytes) = match component {
        ComponentBytes::File(path) => {
            let metadata = std::fs::metadata(path).map_err(|error| GatewayError::new(GatewayErrorCode::Internal, format!("reading {}: {error}", path.display())))?;
            let identity = ComponentFileIdentity {
                path: path.to_path_buf(),
                length: metadata.len(),
                modified_ns: metadata.modified().ok().and_then(|modified| modified.duration_since(std::time::UNIX_EPOCH).ok()).map_or(0, |since| since.as_nanos()),
            };
            match identity.known_hash() {
                Some(package_hash) => (package_hash, None),
                None => {
                    let bytes = read_component(path, scope)?;
                    let package_hash = scoped_component_hash(&bytes, scope)?;
                    identity.remember(package_hash);
                    (package_hash, Some(std::borrow::Cow::Owned(bytes)))
                }
            }
        }
        ComponentBytes::Held(bytes) => (scoped_component_hash(bytes, scope)?, Some(std::borrow::Cow::Borrowed(bytes))),
    };
    if let Some(compiled) = compiled_components().lock().unwrap_or_else(std::sync::PoisonError::into_inner).get(&package_hash) {
        return Ok(compiled.clone());
    }
    scope.enter(ActivationPhase::LoadingCompiledCode).map_err(activation_fault)?;
    let package = semio_framework_plugin_host::PackageRef { package: semio_framework_plugin_host::PackageId(plugin_id.to_string()), hash: semio_framework_plugin_host::PackageHash(package_hash) };
    let compiled = match semio_framework_async::block_on(runtime.load_compiled(&package)) {
        Some(compiled) => compiled,
        None => {
            let bytes = match (bytes.take(), component) {
                (Some(bytes), _) => bytes,
                (None, ComponentBytes::File(path)) => std::borrow::Cow::Owned(read_component(path, scope)?),
                (None, ComponentBytes::Held(bytes)) => std::borrow::Cow::Borrowed(bytes),
            };
            scope.enter(ActivationPhase::CompilingComponent).map_err(activation_fault)?;
            match semio_framework_async::block_on(runtime.isolated_compile_target(&package)) {
                Some(target) => {
                    CompileFlight::join(package_hash, target, &bytes, scope)?;
                    semio_framework_async::block_on(runtime.load_compiled(&package)).ok_or_else(|| GatewayError::new(GatewayErrorCode::Internal, format!("compiling `{plugin_id}`: the isolated compile finished but its compiled code does not load")))?
                }
                None => semio_framework_async::block_on(runtime.compile(&package, &bytes)).map_err(|error| GatewayError::new(GatewayErrorCode::Internal, format!("compiling `{plugin_id}`: {error}")))?,
            }
        }
    };
    compiled_components().lock().unwrap_or_else(std::sync::PoisonError::into_inner).insert(package_hash, compiled.clone());
    Ok(compiled)
}

//#region 🧊️CompileFlight
/// 🧊️ The program an isolated compile runs: this process's own executable (`semio-os-mcp
/// compile-component`) unless a host names another one that answers the same subcommand.
#[cfg(not(target_arch = "wasm32"))]
static COMPONENT_COMPILE_WORKER: OnceLock<PathBuf> = OnceLock::new();

/// 🧊️ Names the program isolated compiles run, for a host whose own executable is not
/// `semio-os-mcp` (a test binary). First call wins.
#[cfg(not(target_arch = "wasm32"))]
pub fn set_component_compile_worker(program: PathBuf) {
    let _ = COMPONENT_COMPILE_WORKER.set(program);
}

/// 🧪️ A unit-test binary is not `semio-os-mcp` and has no `compile-component` subcommand, so under
/// `cfg(test)` the worker is this test binary running exactly [`ISOLATED_COMPILE_TEST_ENTRY`], which
/// reads the same two inputs from its environment.
#[cfg(test)]
pub(crate) const ISOLATED_COMPILE_TEST_ENTRY: &str = "workspace::quick::isolated_compile_worker_entry";
#[cfg(test)]
pub(crate) const ISOLATED_COMPILE_TEST_ENGINE: &str = "SEMIO_ISOLATED_COMPILE_ENGINE";
#[cfg(test)]
pub(crate) const ISOLATED_COMPILE_TEST_OUT: &str = "SEMIO_ISOLATED_COMPILE_OUT";

/// 🔢️ Isolated compile workers this process has started — a shared compile starts exactly one.
#[cfg(not(target_arch = "wasm32"))]
static COMPONENT_COMPILE_WORKERS_STARTED: std::sync::atomic::AtomicU64 = std::sync::atomic::AtomicU64::new(0);

#[cfg(not(target_arch = "wasm32"))]
pub fn component_compile_workers_started() -> u64 {
    COMPONENT_COMPILE_WORKERS_STARTED.load(std::sync::atomic::Ordering::Acquire)
}

/// 🧩️ Brings `bytes` (a component of `plugin_id`) to compiled code in this process under `scope`,
/// exactly as a plugin session's activation does — for a caller that prepares a component ahead of
/// opening it.
#[cfg(not(target_arch = "wasm32"))]
pub fn prepare_plugin_component(plugin_id: &str, bytes: &[u8], scope: &ActivationScope) -> Result<(), GatewayError> {
    let runtime = shared_plugin_runtime()?;
    scoped_compiled_component(runtime.as_ref(), plugin_id, ComponentBytes::Held(bytes), scope).map(drop)
}

/// 🔎️ Isolated compile workers alive right now — zero once every compile finished or was killed.
#[cfg(not(target_arch = "wasm32"))]
pub fn live_component_compile_workers() -> usize {
    compile_flights().lock().unwrap_or_else(std::sync::PoisonError::into_inner).values().filter(|flight| flight.state.lock().unwrap_or_else(std::sync::PoisonError::into_inner).worker.is_some()).count()
}

/// 🧊️ One cold compile of one component, in an isolated worker process, shared by every requester
/// of the same content hash while it runs. A requester that cancels detaches and is answered at
/// once; when the last one detaches the worker is killed, which returns every core and byte the
/// compile held, and its unfinished output is removed. Nothing completes in the background after
/// its last requester is gone. Law: `🏠️workspace/🧫️fixtures/⏱️compile-cancellation-law.json`.
#[cfg(not(target_arch = "wasm32"))]
struct CompileFlight {
    cache_path: PathBuf,
    state: Mutex<CompileFlightState>,
}

#[cfg(not(target_arch = "wasm32"))]
struct CompileFlightState {
    requesters: usize,
    waiters: Vec<semio_framework_async::oneshot::Sender<Result<(), String>>>,
    worker: Option<std::process::Child>,
    outcome: Option<Result<(), String>>,
}

#[cfg(not(target_arch = "wasm32"))]
fn compile_flights() -> &'static Mutex<HashMap<[u8; 32], Arc<CompileFlight>>> {
    static FLIGHTS: OnceLock<Mutex<HashMap<[u8; 32], Arc<CompileFlight>>>> = OnceLock::new();
    FLIGHTS.get_or_init(|| Mutex::new(HashMap::new()))
}

#[cfg(not(target_arch = "wasm32"))]
impl CompileFlight {
    /// 🛫️ Joins the running compile of `package_hash`, or starts it, and waits for it or for the
    /// requester's cancel, whichever comes first.
    fn join(package_hash: [u8; 32], target: semio_framework_plugin_host::IsolatedCompileTarget, bytes: &[u8], scope: &ActivationScope) -> Result<(), GatewayError> {
        let (flight, answer) = {
            let mut flights = compile_flights().lock().unwrap_or_else(std::sync::PoisonError::into_inner);
            let flight = match flights.get(&package_hash) {
                Some(flight) => Arc::clone(flight),
                None => {
                    let flight = Self::launch(package_hash, target, bytes)?;
                    flights.insert(package_hash, Arc::clone(&flight));
                    flight
                }
            };
            let (sender, answer) = semio_framework_async::oneshot::channel();
            let mut state = flight.state.lock().unwrap_or_else(std::sync::PoisonError::into_inner);
            state.requesters += 1;
            match &state.outcome {
                Some(outcome) => drop(sender.send(outcome.clone())),
                None => state.waiters.push(sender),
            }
            drop(state);
            (flight, answer)
        };
        match semio_framework_async::block_on(semio_framework_async::select2(answer, scope.cancel().cancelled())) {
            semio_framework_async::Either::Left(answer) => {
                flight.leave();
                match answer {
                    Ok(Ok(())) => Ok(()),
                    Ok(Err(message)) => Err(GatewayError::new(GatewayErrorCode::Internal, format!("isolated component compile failed: {message}"))),
                    Err(_) => Err(GatewayError::new(GatewayErrorCode::Internal, "the isolated component compile ended without answering")),
                }
            }
            semio_framework_async::Either::Right(()) => {
                flight.detach(package_hash);
                Err(GatewayError::new(GatewayErrorCode::Cancelled, "the caller cancelled while its component was compiling"))
            }
        }
    }

    /// 🚀️ Starts the worker and the thread that feeds it the component and observes its exit.
    fn launch(package_hash: [u8; 32], target: semio_framework_plugin_host::IsolatedCompileTarget, bytes: &[u8]) -> Result<Arc<Self>, GatewayError> {
        let program = match COMPONENT_COMPILE_WORKER.get() {
            Some(program) => program.clone(),
            None => std::env::current_exe().map_err(|error| GatewayError::new(GatewayErrorCode::Internal, format!("locating the compile worker: {error}")))?,
        };
        let mut command = std::process::Command::new(&program);
        command.env_clear();
        if let Some(system_root) = std::env::var_os("SYSTEMROOT") {
            command.env("SYSTEMROOT", system_root);
        }
        #[cfg(not(test))]
        command.arg("compile-component").arg("--engine").arg(&target.engine).arg("--out").arg(&target.cache_path);
        #[cfg(test)]
        command.args([ISOLATED_COMPILE_TEST_ENTRY, "--exact", "--test-threads=1"]).env(ISOLATED_COMPILE_TEST_ENGINE, &target.engine).env(ISOLATED_COMPILE_TEST_OUT, &target.cache_path);
        let mut worker = command
            .stdin(std::process::Stdio::piped())
            .stdout(std::process::Stdio::null())
            .stderr(std::process::Stdio::piped())
            .spawn()
            .map_err(|error| GatewayError::new(GatewayErrorCode::Internal, format!("starting the compile worker {}: {error}", program.display())))?;
        COMPONENT_COMPILE_WORKERS_STARTED.fetch_add(1, std::sync::atomic::Ordering::AcqRel);
        let input = worker.stdin.take().expect("piped compile worker stdin");
        let report = worker.stderr.take().expect("piped compile worker stderr");
        let flight = Arc::new(Self { cache_path: target.cache_path, state: Mutex::new(CompileFlightState { requesters: 0, waiters: Vec::new(), worker: Some(worker), outcome: None }) });
        let observed = Arc::clone(&flight);
        let bytes = bytes.to_vec();
        std::thread::Builder::new()
            .name("semio-compile-flight".to_string())
            .spawn(move || observed.observe(package_hash, input, report, bytes))
            .map_err(|error| GatewayError::new(GatewayErrorCode::Internal, format!("observing the compile worker: {error}")))?;
        Ok(flight)
    }

    /// 👁️ Feeds the worker its component, waits for it to exit — its report closes when it does —
    /// and answers every requester. A worker already killed by the last detach answers no one.
    fn observe(self: Arc<Self>, package_hash: [u8; 32], mut input: std::process::ChildStdin, mut report: std::process::ChildStderr, bytes: Vec<u8>) {
        use std::io::{Read as _, Write as _};
        let _ = input.write_all(&bytes);
        drop(input);
        drop(bytes);
        let mut message = String::new();
        let _ = report.read_to_string(&mut message);
        let mut flights = compile_flights().lock().unwrap_or_else(std::sync::PoisonError::into_inner);
        let mut state = self.state.lock().unwrap_or_else(std::sync::PoisonError::into_inner);
        let Some(mut worker) = state.worker.take() else { return };
        let outcome = match worker.wait() {
            Ok(status) if status.success() => Ok(()),
            Ok(status) => Err(format!("{status}: {}", message.trim())),
            Err(error) => Err(error.to_string()),
        };
        if outcome.is_err() {
            let _ = std::fs::remove_file(semio_framework_plugin_host::compiled_cache_scratch_path(&self.cache_path, worker.id()));
        }
        for waiter in state.waiters.drain(..) {
            let _ = waiter.send(outcome.clone());
        }
        state.outcome = Some(outcome);
        if flights.get(&package_hash).is_some_and(|flight| Arc::ptr_eq(flight, &self)) {
            flights.remove(&package_hash);
        }
    }

    fn leave(&self) {
        let mut state = self.state.lock().unwrap_or_else(std::sync::PoisonError::into_inner);
        state.requesters -= 1;
    }

    /// ✂️ Withdraws one requester; the last one kills the worker and removes its unfinished output.
    fn detach(self: &Arc<Self>, package_hash: [u8; 32]) {
        let mut flights = compile_flights().lock().unwrap_or_else(std::sync::PoisonError::into_inner);
        let mut state = self.state.lock().unwrap_or_else(std::sync::PoisonError::into_inner);
        state.requesters -= 1;
        if state.requesters > 0 || state.outcome.is_some() {
            return;
        }
        if let Some(mut worker) = state.worker.take() {
            let _ = worker.kill();
            let _ = worker.wait();
            let _ = std::fs::remove_file(semio_framework_plugin_host::compiled_cache_scratch_path(&self.cache_path, worker.id()));
        }
        state.waiters.clear();
        state.outcome = Some(Err("every requester cancelled; the compile was killed".to_string()));
        if flights.get(&package_hash).is_some_and(|flight| Arc::ptr_eq(flight, self)) {
            flights.remove(&package_hash);
        }
    }
}
//#endregion 🧊️CompileFlight

#[cfg(not(target_arch = "wasm32"))]
fn shared_compiled_component(runtime: &GuestRuntimes, plugin_id: &str, bytes: &[u8]) -> Result<semio_framework_plugin_host::CompiledHandle, GatewayError> {
    scoped_compiled_component(runtime, plugin_id, ComponentBytes::Held(bytes), &ActivationScope::detached())
}

#[cfg(not(target_arch = "wasm32"))]
impl PluginArtifactChannel {
    fn command_closes_terminal_is_empty(&self) -> bool {
        self.pending_command_closes.terminal_is_empty()
    }

    pub fn new(repo_root: PathBuf, entry: PluginRegistryEntry, descriptor: semio_framework::PackageDescriptor, app_ref: semio_framework::AppRef, actor_label: String) -> Result<Self, GatewayError> {
        let wasm_path = resolve_plugin_wasm_path(&repo_root, &entry)?;
        let runtime = shared_plugin_runtime()?;
        let compiled = scoped_compiled_component(runtime.as_ref(), &entry.plugin_id, ComponentBytes::File(&wasm_path), &ActivationScope::detached())?;
        Ok(Self::from_compiled(runtime, compiled, entry.plugin_id, descriptor, app_ref, actor_label))
    }

    /// 🧩️ Opens a channel over component bytes the caller already holds, whatever their provenance —
    /// a repo build read from disk, or the execution-target component a Hub authorized and served.
    /// Everything past the bytes is identical, which is exactly the point: a hub-bound agent's guest
    /// is the SAME guest a local one gets, not a second code path with its own behaviour.
    pub fn from_component(bytes: &[u8], plugin_id: String, descriptor: semio_framework::PackageDescriptor, app_ref: semio_framework::AppRef, actor_label: String) -> Result<Self, GatewayError> {
        let runtime = shared_plugin_runtime()?;
        let compiled = shared_compiled_component(runtime.as_ref(), &plugin_id, bytes)?;
        Ok(Self::from_compiled(runtime, compiled, plugin_id, descriptor, app_ref, actor_label))
    }

    /// 🧩️ A channel over a component this process already compiled — see [`scoped_compiled_component`].
    fn from_compiled(runtime: Arc<GuestRuntimes>, compiled: semio_framework_plugin_host::CompiledHandle, plugin_id: String, descriptor: semio_framework::PackageDescriptor, app_ref: semio_framework::AppRef, actor_label: String) -> Self {
        Self {
            runtime,
            compiled,
            plugin_id,
            descriptor,
            app_ref,
            actor_label,
            instances: HashMap::new(),
            pending_exchanges: PendingExchangeRegistry::new(),
            pending_command_closes: semio_framework::kernel::CommandDriverRegistry::new(),
            rejected_command_builds: semio_framework::kernel::RejectedCommandBuildRegistry::new(),
            next_seq: 1,
            session_artifact_id: None,
            session_documents: HashMap::new(),
            backbone_egress: Vec::new(),
            backbone_bindings: std::collections::BTreeSet::new(),
            inference: None,
        }
    }

    /// 🧵️ Takes every document-backbone message this guest has published since the last drain. The
    /// caller owns the relay: this channel knows the plugin, not the document actor.
    pub fn drain_backbone_egress(&mut self) -> Vec<Vec<u8>> {
        std::mem::take(&mut self.backbone_egress)
    }

    /// 🧵️ Binds this guest instance's DOCUMENT BACKBONE to this channel's own actor uri, once.
    ///
    /// 🐛️ A guest publishes `Effect::SendMessage { target: Backbone { uri } }` **only for an
    /// instance a host has explicitly bound** (`🔌️plugin/🦀️.rs`'s
    /// `plugin_handle_document_backbone_binding` → `document_backbone_effects`). Without this
    /// command the agent's committed transaction is real inside the guest — `action_invoke` answers
    /// `SUCCEEDED` with a moved `headEditId` — and its envelopes are published to nobody, so the hub
    /// ledger stays at `head_seq 0`. Measured live on hub 7681, 2026-09-22
    /// (`🗑️generated/m10-7681-note-status-after.txt`): an invoke that succeeded against a document
    /// whose ledger never moved. A silent success is the worst shape this lane can have, which is
    /// why the bind is a hard precondition of dispatch rather than a best-effort extra.
    ///
    /// 🪢 The uri is [`Self::actor_label`]'s value, which is the SAME string
    /// [`document_backbone_payload`] fences egress on — bind and relay cannot drift apart because
    /// they read one field.
    ///
    /// 🧭️ Ordering: the guest refuses a bind-then-load
    /// (`plugin.document-backbone.load-while-bound`), so this runs AFTER
    /// [`Self::load_session_document`], never before.
    ///
    /// 🧵️ A bind turn can already carry egress — the guest flushes whatever its store had
    /// pending onto the freshly bound backbone — so it is captured here exactly as a command
    /// turn's is, rather than left in the turn and lost.
    fn ensure_document_backbone(&mut self, instance: u32) -> Result<(), Fault> {
        if self.backbone_bindings.contains(&instance) {
            return Ok(());
        }
        self.ensure_instance(instance)?;
        let command = semio_framework_plugin::document_backbone_binding::DocumentBackboneBindingCommandV1 {
            operation: semio_framework_plugin::document_backbone_binding::DocumentBackboneBindingOperationV1::Bind,
            instance_id: instance,
            binding_generation: DOCUMENT_BACKBONE_BINDING_GENERATION,
            uri: self.actor_label.clone(),
        };
        let payload = command.encode().map_err(|error| Self::not_wired("document-backbone bind", error))?;
        let event = semio_framework::kernel::Event::Message { source: semio_framework::kernel::MessageEndpoint::Shell { instance: semio_framework::kernel::PluginInstanceId(instance.to_string()) }, payload };
        let runtime = Arc::clone(&self.runtime);
        let guest = self.instances.get_mut(&instance).ok_or_else(|| Self::not_wired("document-backbone bind", format!("no open instance {instance}")))?;
        let turn = semio_framework_async::block_on(runtime.execute_turn(guest, std::slice::from_ref(&event), headless_command_budget())).map_err(|error| Self::not_wired("document-backbone bind", error))?;
        let receipts: Vec<&Vec<u8>> = turn
            .effects
            .iter()
            .filter_map(|effect| match effect {
                semio_framework::kernel::Effect::SendMessage { target: semio_framework::kernel::MessageEndpoint::Shell { instance: target }, payload } if target.0 == instance.to_string() => Some(payload),
                _ => None,
            })
            .collect();
        if receipts.len() != 1 {
            return Err(Self::not_wired("document-backbone bind", format!("the guest answered {} shell receipt(s) for one bind", receipts.len())));
        }
        semio_framework_plugin::document_backbone_binding::require_document_backbone_binding_receipt_v1(receipts[0], &command).map_err(|error| Self::not_wired("document-backbone bind", error))?;
        for effect in &turn.effects {
            if let Some(egress) = document_backbone_payload(&self.actor_label, effect) {
                self.backbone_egress.push(egress.to_vec());
            }
        }
        self.backbone_bindings.insert(instance);
        Ok(())
    }

    /// 🗿️ Names the artifact this channel's guest session document is, for the stamps it answers.
    /// `None` means the owning workspace has bound no artifact to this plugin, or more than one —
    /// see [`Self::session_artifact_id`].
    pub fn bind_session_artifact(&mut self, artifact_id: Option<String>) {
        self.session_artifact_id = artifact_id;
    }

    /// 📥️ Makes `artifact_id`'s canonical pair this guest's session document — one
    /// `AppCommand::LoadDocument`, the SAME verb the shell's own open path and this file's
    /// `ExportMedia` arm already drive, so nothing about the bytes is interpreted here.
    ///
    /// 🧭️ Idempotent per guest: a channel that already holds this artifact's pair does nothing, so
    /// the load happens once per (instance, artifact) and never once per command — re-loading on
    /// every exchange would discard the guest's own uncommitted transaction state between
    /// `TransactionPrepare` and `TransactionCommit`, which is the whole two-phase contract.
    /// [`Self::discard_instance`] forgets it, because a thrown-away guest holds nothing.
    ///
    /// 🔀️ A guest that holds ANOTHER artifact (its app's session document moved to a document the agent opened since,
    /// [`route_session_artifact`]) is thrown away first: a guest is only ever seeded fresh, never while its backbone is
    /// bound to a different document.
    ///
    /// 🏁️ `LoadDocument` publishes no frame of its own, so its answer is the stamped
    /// `AppFrame::Done` `await_response` mints — see [`PendingResponsePage::Stamped`].
    pub fn load_session_document(&mut self, instance: u32, artifact_id: &str, pack: &[u8], spr: &[u8]) -> Result<(), Fault> {
        match self.session_documents.get(&instance) {
            Some(loaded) if loaded == artifact_id => return Ok(()),
            Some(_) => self.discard_instance(instance),
            None => {}
        }
        self.ensure_instance(instance)?;
        match self.exchange_one_real(instance, store::AppCommand::LoadDocument { seq: 0, pack: pack.to_vec(), spr: spr.to_vec() })? {
            store::AppFrame::Done { .. } => {}
            store::AppFrame::Error { fault, .. } => return Err(decode_guest_fault(&fault)),
            other => return Err(Self::not_wired("LoadDocument", format!("unexpected real AppFrame variant {other:?}"))),
        }
        self.session_documents.insert(instance, artifact_id.to_string());
        Ok(())
    }

    /// 🔁️ Throws this guest's session document away so the next [`Self::load_session_document`] seeds
    /// it from a new baseline — a guest can only be reseeded fresh, never while its backbone is bound.
    pub fn reseed_session_document(&mut self, instance: u32) {
        self.discard_instance(instance);
    }

    /// 📥️ Hands one mutation batch the hub document's actor delivered to this guest's bound document
    /// backbone — the same `Event::Message { source: Backbone }` turn the wgpu and React shells drive
    /// (`ProgramBridge::receive_document_backbone`) — and drives the guest until it is idle. Whatever it
    /// publishes back onto the backbone is kept for the relay, and an `AppFrame::Error` it answers on
    /// its shell lane is the refusal it is.
    pub fn receive_document_backbone(&mut self, instance: u32, message: Vec<u8>) -> Result<(), Fault> {
        store::decode_hot_backbone_message_exact(&message).map_err(|error| Self::not_wired("document-backbone ingress", error))?;
        self.ensure_instance(instance)?;
        let mut owed = vec![semio_framework::kernel::Event::Message { source: semio_framework::kernel::MessageEndpoint::Backbone { uri: self.actor_label.clone() }, payload: message }];
        let deadline = std::time::Instant::now() + COMMAND_RESUME_WALL_BUDGET;
        loop {
            let events = std::mem::take(&mut owed);
            let runtime = Arc::clone(&self.runtime);
            let guest = self.instances.get_mut(&instance).ok_or_else(|| Self::not_wired("document-backbone ingress", format!("no open instance {instance}")))?;
            let turn = match semio_framework_async::block_on(runtime.execute_turn(guest, &events, headless_command_budget())) {
                Ok(turn) => turn,
                Err(error) => {
                    self.discard_instance(instance);
                    return Err(Self::not_wired("document-backbone ingress", format!("{error}; the instance was discarded")));
                }
            };
            for effect in &turn.effects {
                if let Some(egress) = document_backbone_payload(&self.actor_label, effect) {
                    self.backbone_egress.push(egress.to_vec());
                }
                if let Some(fault) = shell_lane_fault(instance, effect) {
                    return Err(fault);
                }
            }
            if let Some(receipt) = turn.lifecycle_receipt {
                owed.push(semio_framework::kernel::Event::InstanceLifecycleAck(semio_framework::kernel::ActorInstanceLifecycleAck { receipt }));
            }
            match turn.status {
                semio_framework::kernel::TurnStatus::Idle if owed.is_empty() => return Ok(()),
                semio_framework::kernel::TurnStatus::Faulted(detail) => return Err(decode_guest_fault(&detail)),
                _ if owed.is_empty() => owed.push(semio_framework::kernel::Event::Wake),
                _ => {}
            }
            if std::time::Instant::now() >= deadline {
                return Err(Self::budget_fault("document-backbone ingress"));
            }
        }
    }

    /// 🗿️ What a `RevisionStamp` from this channel names. A channel with no bound artifact answers
    /// the plugin-scoped session pseudo-id `plugin:<id>` — which is what the document IS in that
    /// case, a plugin's genesis session no client can address — never the bare plugin id, which a
    /// client would read as an artifact id and pass straight back into `artifact_snapshot`.
    fn stamped_artifact_id(&self) -> String {
        self.session_artifact_id.clone().unwrap_or_else(|| format!("plugin:{}", self.plugin_id))
    }

    /// 💡️ Opens (once) this plugin's real inference route: a fresh `GuestRuntimes` over the SAME
    /// compiled component, one `PluginInstanceHandle`, and an `ArtifactInferenceRouter` registered
    /// with the plugin's own declared roster — byte-for-byte the `serde_json` roster
    /// `🏃️run/🦀️.rs` builds (`contributions.inference_services` chained with every
    /// `artifact_contributions[].inferences`). A plugin that declares no inference at all is a
    /// typed refusal here rather than an empty registration that would fail later with a worse
    /// message.
    ///
    /// 🐎️ The SAME runtime the command lane uses, not a second one: `self.compiled` carries a
    /// `wasmtime::Component` that only its own `Engine` can instantiate. The inference lane is
    /// still a SEPARATE guest instance on its own actor ordinal — `PluginInstanceHandle` takes
    /// ownership of the instance it drives — it just shares the engine and the compiled code.
    fn ensure_inference_route(&mut self) -> Result<&PluginInferenceRoute, Fault> {
        if self.inference.is_none() {
            let roster: Vec<serde_json::Value> = self
                .descriptor
                .contributions
                .inference_services
                .iter()
                .chain(self.descriptor.contributions.artifact_contributions.iter().flat_map(|contribution| contribution.inferences.iter()))
                .map(serde_json::to_value)
                .collect::<Result<Vec<_>, _>>()
                .map_err(|error| Self::not_wired("inference roster", error))?;
            if roster.is_empty() {
                return Err(Fault { code: "capability.not-found".to_string(), message: format!("plugin `{}` declares no inference service in its committed descriptor", self.plugin_id) });
            }
            let roster_bytes = serde_json::to_vec(&roster).map_err(|error| Self::not_wired("inference roster", error))?;
            let actor = ::semio_framework_async::poll::resolve_ready(semio_framework_actor::ActorId::new(INFERENCE_ACTOR_ORDINAL, 0, 1, 0));
            let caps: Vec<semio_framework::kernel::BrokerCapabilityGrant> =
                self.descriptor.capability_requests.iter().map(|request| semio_framework::kernel::BrokerCapabilityGrant { token: semio_framework::CapabilityToken(0), id: request.id.clone(), scope: request.scope.clone(), expires_ms: None }).collect();
            let runtimes = Arc::clone(&self.runtime);
            let budget = headless_inference_budget();
            let instance = semio_framework_async::block_on(semio_framework_plugin_host::GuestRuntime::instantiate(runtimes.as_ref(), &self.compiled, actor, &caps, &budget)).map_err(|error| Self::not_wired("inference instantiate", error))?;
            let handle = Arc::new(semio_framework_async::block_on(semio_framework_plugin_host::PluginInstanceHandle::new(actor, Arc::clone(&runtimes), instance)));
            let router = semio_framework_plugin_host::ArtifactInferenceRouter::new();
            semio_framework_async::block_on(router.register_plugin(&self.plugin_id, &self.descriptor.manifest.dependencies, handle, &roster_bytes)).map_err(|error| Self::not_wired("inference route registration", error))?;
            self.inference = Some(PluginInferenceRoute { router });
        }
        Ok(self.inference.as_ref().expect("inference route was just opened"))
    }

    /// 💡️ Runs ONE declared inference through the real router — the general replacement for the old
    /// blanket `channel.not-wired`. The router resolves the route, toposorts and injects
    /// `dependsOn` results, drives the guest's `semio.infer` cold job, validates the guest's echo
    /// field-for-field and re-checks commit freshness; this function only builds the request wire
    /// and decodes the result, and reports whatever the router answers verbatim.
    ///
    /// 🗣️ The artifact schema's own canonical identity, exactly as the plugin committed it.
    /// It is an `ArtifactIdentity`, which the guest validates with `ArtifactIdentity::parse`
    /// (`🔌️plugin/🦀️.rs`, `validate_wire_request_resources`): dot-delimited segments of
    /// `[a-z0-9_-]` only. The `<kind>@<schemaVersion>/*` form this used to send is the
    /// CAPABILITY-id grammar, not an identity — `@`, `/` and `*` are all non-canonical
    /// segment bytes, so every real inference died `artifact-inference.source-dialect:
    /// identity "s.wfc.bitmap@1/*" has a non-canonical segment` before the guest ran a
    /// single step (measured 2026-09-22, slice CE3). The version is not lost by dropping the
    /// suffix: `artifact_schema_version` is its own field on this same request.
    fn infer_real(&mut self, command: &crate::actions::InferCommand) -> Result<crate::schema::ArtifactInferenceResultV1, Fault> {
        let declared = self
            .descriptor
            .contributions
            .inference_services
            .iter()
            .chain(self.descriptor.contributions.artifact_contributions.iter().flat_map(|contribution| contribution.inferences.iter()))
            .find(|item| item.artifact_kind == command.artifact_kind && item.inference_schema == command.inference_schema)
            .cloned()
            .ok_or_else(|| Fault {
                code: "capability.not-found".to_string(),
                message: format!("plugin `{}` declares no inference `{}` on artifact kind `{}`", self.plugin_id, command.inference_schema, command.artifact_kind),
            })?;
        let request = crate::schema::ArtifactInferenceRequestV1 {
            wire_version: crate::schema::ARTIFACT_INFERENCE_WIRE_VERSION,
            owner: declared.owner.clone(),
            artifact_kind: declared.artifact_kind.clone(),
            artifact_schema: declared.artifact_schema.clone(),
            artifact_schema_version: declared.artifact_schema_version,
            inference_schema: declared.inference_schema.clone(),
            inference_schema_version: declared.inference_schema_version,
            algorithm_version: declared.algorithm_version,
            policy_version: declared.policy_version,
            revision: command.revision,
            generation: command.generation,
            source_dialect: declared.artifact_schema.clone(),
            policy: Vec::new(),
            budgets: crate::schema::ArtifactInferenceBudgetV1 { allocation_bytes: INFERENCE_ALLOCATION_BYTES, work_units: command.work_units.max(1), recursion_depth: INFERENCE_RECURSION_DEPTH },
            cancellation_id: command.cancellation_id.clone(),
            previous_state: None,
            requested_cache_mode: crate::schema::ArtifactInferenceCacheModeV1::Cold,
            canonical_payload: bind_inference_document(&declared, command)?,
            dependencies: Vec::new(),
        };
        let request_bytes = serde_json::to_vec(&request).map_err(|error| Self::not_wired("encoding the inference request", error))?;
        let route = self.ensure_inference_route()?;
        let result_bytes = semio_framework_async::block_on(route.router.infer(&request_bytes, &command.cancel.0)).map_err(|error| Fault { code: "app.command.rejected".to_string(), message: format!("`{}` refused: {error}", request.inference_schema) })?;
        serde_json::from_slice(&result_bytes).map_err(|error| Self::not_wired("decoding the inference result", error))
    }

    /// 🎯️ The owner-qualified address a typed command frame needs, resolved out of the plugin's OWN
    /// committed manifest rather than parsed out of the capability id's punctuation.
    ///
    /// 🗂️ The walk is `🗂️catalog`'s own `app_action_verbs` walk, in the same order and with the same
    /// precedence, so the address this builds always names the window kind the catalog published the
    /// verb under: window-kind declarations first, then APP-scope actions (`🗒️note` declares all 48
    /// of its verbs this way) under the catalog's own `"*"` marker for "belongs to no particular
    /// window". Recomputing the catalog's id (`{plugin}.{app}.{action}`) and comparing is what keeps
    /// the two in step — an app id is itself a dotted canonical surface ref
    /// (`s.draw.drawing@1/*#editor`), so splitting the id on `.` could never have recovered it.
    ///
    /// 🪟️ `window_instance_id` is the window kind's own id, which is exactly what the React shell's
    /// `sessionWindowInstances` mints for a freshly opened app (`app.windowKinds.map(kind => ({id:
    /// kind.id, …}))`) — an agent therefore addresses the very pane a human's first window is,
    /// rather than a synthetic id no shell would ever produce.
    fn addressed_action_invocation(&self, capability_id: &str, input: &serde_json::Value) -> Result<semio_framework::manifest::ActionInvocation, Fault> {
        let plugin_id = self.plugin_id.as_str();
        let mut address: Option<semio_framework::manifest::ActionAddress> = None;
        'apps: for app in self.descriptor.manifest.apps.iter() {
            let base_window = app.window_kinds.iter().next().map(|kind| kind.id.clone());
            for window_kind in app.window_kinds.iter() {
                for action in window_kind.actions.iter() {
                    if capability_id == format!("{plugin_id}.{}.{}", app.id, action.id) {
                        address = Some(semio_framework::manifest::ActionAddress {
                            plugin_id: plugin_id.to_string(),
                            app_id: app.id.clone(),
                            mode_id: app.default_mode_id.clone(),
                            window_kind_id: window_kind.id.clone(),
                            window_instance_id: window_kind.id.clone(),
                            action_id: action.id.clone(),
                        });
                        break 'apps;
                    }
                }
            }
            for action in app.actions.iter() {
                if capability_id == format!("{plugin_id}.{}.{}", app.id, action.id) {
                    let Some(window_instance_id) = base_window.clone() else {
                        return Err(Self::not_wired("PureCommand", format!("app `{}` declares action `{}` but no window kind at all, so there is no pane an agent could address it in", app.id, action.id)));
                    };
                    address = Some(semio_framework::manifest::ActionAddress {
                        plugin_id: plugin_id.to_string(),
                        app_id: app.id.clone(),
                        mode_id: app.default_mode_id.clone(),
                        window_kind_id: "*".to_string(),
                        window_instance_id,
                        action_id: action.id.clone(),
                    });
                    break 'apps;
                }
            }
        }
        let address = address.ok_or_else(|| Fault {
            code: "capability.not-found".to_string(),
            message: format!("plugin `{plugin_id}` declares no app action named by capability `{capability_id}` — its committed manifest publishes {} app(s)", self.descriptor.manifest.apps.len()),
        })?;
        let arguments = match input {
            serde_json::Value::Object(map) => map.iter().map(|(key, value)| (key.clone(), store::DslValue::from(value))).collect(),
            serde_json::Value::Null => std::collections::BTreeMap::new(),
            other => return Err(Self::not_wired("PureCommand", format!("an action's input is a named argument object; this call carried {other}"))),
        };
        Ok(semio_framework::manifest::ActionInvocation { address, arguments })
    }

    fn not_wired(what: &str, detail: impl std::fmt::Display) -> Fault {
        Fault { code: "channel.not-wired".to_string(), message: format!("{what}: {detail}") }
    }

    fn budget_fault(what: &str) -> Fault {
        Fault { code: "budget.exceeded".to_string(), message: format!("{what} reached its wall budget before it settled") }
    }

    /// ☠️ Throws an instance away. A turn cut by an epoch deadline or a trap leaves the component
    /// instance mid-call — wasmtime answers `cannot enter component instance` for every later call —
    /// so there is nothing to resume and nothing to salvage; the next `ensure_instance` builds a
    /// fresh one. `drop_instance` is driven rather than relying on `Drop` because it is what the
    /// `GuestRuntime` contract names for closing an instance, and under wasmtime it is exactly the
    /// `Store` release the pooling allocator needs to reclaim the slab.
    fn discard_instance(&mut self, instance: u32) {
        self.session_documents.remove(&instance);
        self.backbone_bindings.remove(&instance);
        if let Some(guest) = self.instances.remove(&instance) {
            semio_framework_async::block_on(self.runtime.drop_instance(guest));
        }
    }

    /// 🎬️ Opens `instance`'s guest and drives it to settle: `Event::InstanceOpen`, then the
    /// `InstanceLifecycleAck` for whatever receipt that open published, until the guest reports
    /// `Idle` with nothing owed. Bounded by [`INSTANCE_OPEN_WALL_BUDGET`], with each turn bounded by
    /// [`headless_open_budget`].
    ///
    /// 🐎️ The mid-flight pump this replaces (slices, an `undelivered` queue, a `turn_in_flight`
    /// guard) existed because an OWNED-interpreter turn can yield mid-call and refuse new events
    /// until it settles. A compiled turn is atomic — it returns a `TurnResult` or it faults — so the
    /// queue has nothing to hold and the guard nothing to guard. What survives the move is the part
    /// that was never about the runtime: the acknowledgement below.
    ///
    /// 🧾️ The guest's `ActorInstanceLifecycleReceipt` is acknowledged here. An open the host never
    /// acknowledges is retained state the guest re-offers on every later turn — `🖥️host`'s own
    /// `🔬️poll-turn-memory` law measures exactly that — so without this the instance never reaches
    /// `Idle` and every command afterwards pays for an open that never finished.
    ///
    /// ♻️ The guest's own retained lifecycle-deadline verdict is runtime-independent too: it is the
    /// guest saying "I kept my progress, ask me again", so the events it did not consume are
    /// re-offered on the next turn rather than lost.
    fn ensure_instance(&mut self, instance: u32) -> Result<(), Fault> {
        self.ensure_instance_scoped(instance, &ActivationScope::detached())
    }

    /// 🎬️ [`Self::ensure_instance`] under a caller's progress and cancel: a cancel observed between
    /// turns throws the half-open guest away, so the next open starts clean.
    ///
    /// 🎟️ The grants are handed to `instantiate` — the store's capability table is built with the
    /// instance — and travel in `Event::InstanceOpen` as well, which is where the guest reads them.
    ///
    /// ⏱️ A compiled turn cut by its own ceiling is not a yield to resume from: the
    /// instance is mid-call and unusable. Report it as the bounded budget fault it is,
    /// rather than as a wiring fault, and throw the half-open instance away.
    fn ensure_instance_scoped(&mut self, instance: u32, scope: &ActivationScope) -> Result<(), Fault> {
        if self.instances.contains_key(&instance) {
            return Ok(());
        }
        scope.enter(ActivationPhase::OpeningGuest)?;
        let actor = ::semio_framework_async::poll::resolve_ready(semio_framework_actor::ActorId::new((instance as u16).wrapping_add(1), 0, 1, 0));
        let caps: Vec<semio_framework::kernel::BrokerCapabilityGrant> = self
            .descriptor
            .capability_requests
            .iter()
            .map(|request| semio_framework::kernel::BrokerCapabilityGrant { token: semio_framework::CapabilityToken(0), id: request.id.clone(), scope: request.scope.clone(), expires_ms: None })
            .collect();
        let budget = headless_open_budget();
        let mut guest = semio_framework_async::block_on(self.runtime.instantiate(&self.compiled, actor, &caps, &budget)).map_err(|error| Self::not_wired("instantiate", error))?;
        let mut owed = vec![semio_framework::kernel::Event::InstanceOpen {
            request: semio_framework::kernel::ActorInstanceOpenRequest { activation_generation: 1, instance_id: instance, request_sequence: 1 },
            app_id: semio_framework::kernel::AppInstanceId(self.app_ref.app_id.clone()),
            actor: self.actor_label.clone(),
            config: Vec::new(),
            assets: Vec::new(),
            capabilities: caps,
            quotas: self.descriptor.quotas.clone(),
        }];
        let deadline = std::time::Instant::now() + INSTANCE_OPEN_WALL_BUDGET;
        loop {
            let events = std::mem::take(&mut owed);
            match semio_framework_async::block_on(self.runtime.execute_turn(&mut guest, &events, headless_open_budget())) {
                Ok(turn) => {
                    if let Some(receipt) = turn.lifecycle_receipt {
                        owed.push(semio_framework::kernel::Event::InstanceLifecycleAck(semio_framework::kernel::ActorInstanceLifecycleAck { receipt }));
                    }
                    if matches!(turn.status, semio_framework::kernel::TurnStatus::Idle) && owed.is_empty() {
                        self.instances.insert(instance, guest);
                        return Ok(());
                    }
                }
                Err(error) if semio_framework_plugin_host::retryable_lifecycle_turn(&error, &events) => {
                    owed.splice(0..0, events);
                }
                Err(error @ (semio_framework_plugin_host::TurnFault::DeadlineExceeded | semio_framework_plugin_host::TurnFault::FuelExhausted)) => {
                    semio_framework_async::block_on(self.runtime.drop_instance(guest));
                    return Err(Fault { code: "budget.exceeded".to_string(), message: format!("InstanceOpen exceeded one turn's ceiling ({error}); the guest never came up") });
                }
                Err(error) => {
                    semio_framework_async::block_on(self.runtime.drop_instance(guest));
                    return Err(Self::not_wired("InstanceOpen", error));
                }
            }
            if let Err(cancelled) = scope.checkpoint() {
                semio_framework_async::block_on(self.runtime.drop_instance(guest));
                return Err(cancelled);
            }
            if std::time::Instant::now() >= deadline {
                semio_framework_async::block_on(self.runtime.drop_instance(guest));
                return Err(Self::budget_fault("InstanceOpen"));
            }
        }
    }

    /// 🔁️ Drives one `AppCommand` to its terminal frame. The command becomes a retained host batch
    /// whose exact current page is handed to one guest turn; the next page stays untouched until the
    /// guest acknowledges the one before it, so a command of N pages is N+1 turns. An interactive
    /// host takes those turns off its own frame loop; a headless gateway has no next frame, so it
    /// takes them here, bounded by [`COMMAND_RESUME_WALL_BUDGET`] and never unbounded.
    ///
    /// 🔢️ ONE sequence for the whole command, stamped into the command itself before it is
    /// encoded. The kernel envelope and the `AppCommand` must carry the same number: the guest
    /// answers with an `AppFrame` whose `in_reply_to` is the COMMAND's `seq`. Every call site in
    /// this file used to pass a literal `seq: 0` while the envelope counted from 1, so even a host
    /// reading the right lane would have correlated nothing.
    fn exchange_one_real(&mut self, instance: u32, mut real_command: store::AppCommand) -> Result<store::AppFrame, Fault> {
        let seq = self.next_seq;
        self.next_seq += 1;
        *app_command_seq_mut(&mut real_command) = seq;
        let deadline = std::time::Instant::now() + COMMAND_RESUME_WALL_BUDGET;
        loop {
            match self.exchange_one_turn(instance, &real_command, seq)? {
                CommandTurn::Settled(frame) => return Ok(frame),
                CommandTurn::MoreWork if std::time::Instant::now() < deadline => continue,
                CommandTurn::MoreWork => {
                    self.discard_instance(instance);
                    return Err(Fault { code: "budget.exceeded".to_string(), message: format!("AppCommand seq {seq} reached its wall budget before it settled; the instance was discarded and the next command starts on a fresh one") });
                }
            }
        }
    }

    /// 🔁️ ONE guest turn, or one bounded host-side bookkeeping step, of the command above. Returns
    /// [`CommandTurn::MoreWork`] when the command genuinely owes another one — the guest has more
    /// retained pages to read, or a fixed-capacity registry is mid-teardown — and a `Fault` only
    /// when the command is over. The two used to be the same value: every "call me again" was minted
    /// as a `budget.exceeded` fault and the loop above re-entered on the fault's CODE, so a real
    /// budget failure and normal paging were indistinguishable both to the loop and to the agent
    /// reading the message.
    ///
    /// 📄️ One retained page per turn. Under a compiled runtime every turn completes, so the
    /// cursor always advances here; when the driver has no page left the guest is woken instead,
    /// which is how it gets to publish its terminal acknowledgement.
    ///
    /// ⏱️ The suspension window is "while this guest turn runs, nobody touches the driver", so
    /// it is closed on every arm, not just the `Ok` one: leaving the driver `Suspended` (and
    /// linked for close) made the next turn read `!is_active`, tear the whole command down and
    /// re-send it under a BRAND NEW `seq` while the guest still retained the owner of the
    /// first attempt — the whole of `plugin.command-cursor-mismatch: owner is 1, the retained
    /// owner's is 554` (ticket 26/09/18 slice A2 §6.1). The instance itself is gone either
    /// way: a turn cut by its ceiling leaves the component mid-call and unusable.
    ///
    /// 🧾️ The guest's OWN reason for refusing the ingress rides in `command_ingress`, and
    /// the cleanup below takes further turns — so it is captured on the exchange the
    /// moment it is seen, not read again at the terminal where it no longer exists. It
    /// used to be dropped entirely, and "faulted for seq N after bounded exact-owner
    /// cleanup" told the agent (and every earlier slice of this ticket) nothing at all.
    ///
    /// 🧹️ An exchange left behind by an ABANDONED command — its wall budget ran out, or its guest turn faulted and the
    /// instance was discarded — is closed step by step before the next command on the instance is admitted. It used to
    /// stay active, and the next command's turn met it with `assert_eq!(pending.seq, seq)`: the gateway's main thread
    /// panicked and every MCP session on it died (live hub coverage on 7800/p33, ticket 26/09/23 G12 session 14c).
    fn exchange_one_turn(&mut self, instance: u32, real_command: &store::AppCommand, seq: u64) -> Result<CommandTurn, Fault> {
        if !self.rejected_command_builds.terminal_is_empty() {
            self.rejected_command_builds.close_step(semio_framework::kernel::COMMAND_PAGE_MAXIMUM_BYTES);
            return Ok(CommandTurn::MoreWork);
        }
        begin_closing_abandoned_exchange(&self.pending_exchanges, &mut self.pending_command_closes, instance, seq)?;
        if let Some(seq) = self.pending_exchanges.get(instance).map(|pending| pending.seq) {
            if !self.pending_command_closes.is_active(u64::from(instance), seq) {
                let (response_complete, _) = self.pending_exchanges.close_response_step(instance, semio_framework::kernel::COMMAND_PAGE_MAXIMUM_BYTES);
                if !response_complete {
                    return Ok(CommandTurn::MoreWork);
                }
                let (complete, _, _) = self.pending_command_closes.close_step(semio_framework::kernel::COMMAND_PAGE_MAXIMUM_BYTES);
                if complete {
                    let terminal = self.pending_exchanges.remove(instance).expect("closed pending exchange reached terminal empty");
                    assert!(terminal.response.terminal_is_empty(), "closed pending response reached terminal empty");
                }
                return Ok(CommandTurn::MoreWork);
            }
        }
        if self.pending_exchanges.get(instance).is_none() && !persistent_command_completion_port_ready() {
            return Err(Self::not_wired("AppCommand", "persistent command completion submit/poll/cancel authority is not admitted"));
        }
        if self.pending_exchanges.get(instance).is_none() {
            if !self.pending_exchanges.can_insert(instance) || !self.pending_command_closes.can_insert(u64::from(instance)) || !self.rejected_command_builds.can_insert(u64::from(instance)) {
                return Err(Fault { code: "budget.exceeded".to_string(), message: "fixed pending command authority is saturated or collided".to_string() });
            }
            let command = ::semio_framework_async::poll::resolve_ready(store::encode_app_command(real_command)).map_err(|fault| Self::not_wired("encoding AppCommand", format!("{}: {}", fault.code.0, fault.message)))?;
            let envelope = semio_framework::kernel::CommandEnvelope { instance, seq, command };
            let mut owners = semio_framework::kernel::CommandEnvelopeSet::try_new().map_err(|fault| Self::not_wired("reserving command batch", format!("{}: {}", fault.code.0, fault.message)))?;
            if let Err((fault, rejected)) = owners.try_push(envelope) {
                self.rejected_command_builds.insert_admitted(u64::from(instance), semio_framework::kernel::RejectedCommandBuild::new(owners, rejected));
                return Err(Self::not_wired("admitting command owner", format!("{}: {}", fault.code.0, fault.message)));
            }
            let batch = match semio_framework::kernel::CommandBatch::try_new(seq, owners) {
                Ok(batch) => batch,
                Err((fault, owners)) => {
                    self.rejected_command_builds.insert_admitted(u64::from(instance), semio_framework::kernel::RejectedCommandBuild::from_admitted(owners));
                    return Err(Self::not_wired("admitting command batch", format!("{}: {}", fault.code.0, fault.message)));
                }
            };
            self.pending_command_closes.insert_admitted(u64::from(instance), seq, semio_framework::kernel::CommandBatchDriver::new(seq, batch));
            self.pending_exchanges.insert_admitted(PendingExchange { instance, seq, response: PendingResponsePage::Empty, ingress_fault: None });
        }
        assert_eq!(self.pending_exchanges.get(instance).expect("pending exchange was admitted").seq, seq, "the retained exchange answers the command this turn drives");
        let event = self
            .pending_command_closes
            .with_driver_mut(u64::from(instance), seq, |driver| driver.next_page())
            .map_err(|fault| Self::not_wired("retained command driver", format!("{}: {}", fault.code.0, fault.message)))?
            .map_err(|fault| Self::not_wired("command page", format!("{}: {}", fault.code.0, fault.message)))?
            .map(|(cursor, bytes)| semio_framework::kernel::Event::CommandIngressPage { cursor, bytes })
            .unwrap_or(semio_framework::kernel::Event::Wake);
        let runtime = Arc::clone(&self.runtime);
        let guest = self.instances.get_mut(&instance).ok_or_else(|| Self::not_wired("exchange", format!("no open instance {instance}")))?;
        self.pending_command_closes.prepare_suspend(u64::from(instance), seq).map_err(|fault| Self::not_wired("suspending command owner", format!("{}: {}", fault.code.0, fault.message)))?;
        let outcome = semio_framework_async::block_on(runtime.execute_turn(guest, std::slice::from_ref(&event), headless_command_budget()));
        let turn = match outcome {
            Ok(turn) => {
                self.pending_command_closes.resume(u64::from(instance), seq).map_err(|fault| Self::not_wired("resuming command owner", format!("{}: {}", fault.code.0, fault.message)))?;
                turn
            }
            Err(error) => {
                self.pending_command_closes.resume(u64::from(instance), seq).map_err(|fault| Self::not_wired("resuming command owner", format!("{}: {}", fault.code.0, fault.message)))?;
                self.discard_instance(instance);
                return Err(match error {
                    semio_framework_plugin_host::TurnFault::DeadlineExceeded | semio_framework_plugin_host::TurnFault::FuelExhausted => {
                        Fault { code: "budget.exceeded".to_string(), message: format!("AppCommand exceeded one turn's ceiling ({error}); the instance was discarded") }
                    }
                    error => Self::not_wired("execute_turn", error),
                });
            }
        };
        let progress = self
            .pending_command_closes
            .with_driver_mut(u64::from(instance), seq, |driver| driver.observe(&turn.command_ingress, semio_framework::kernel::COMMAND_PAGE_MAXIMUM_BYTES))
            .map_err(|fault| Self::not_wired("retained command driver", format!("{}: {}", fault.code.0, fault.message)))?
            .map_err(|fault| Self::not_wired("command acknowledgement", format!("{}: {} — the guest answered {:?} while this gateway drives instance {instance} seq {seq}", fault.code.0, fault.message, turn.command_ingress)))?;
        let mut published: Vec<String> = Vec::new();
        let mut backbone_egress: Vec<Vec<u8>> = Vec::new();
        for effect in &turn.effects {
            published.push(effect_shape(instance, effect));
            if let Some(payload) = document_backbone_payload(&self.actor_label, effect) {
                backbone_egress.push(payload.to_vec());
            }
            Self::admit_reply_frame(self.pending_exchanges.get_mut(instance).expect("pending exchange was admitted"), instance, seq, effect);
        }
        self.backbone_egress.append(&mut backbone_egress);
        match progress {
            semio_framework::kernel::CommandBatchProgress::Complete => {
                self.pending_command_closes.remove_terminal(u64::from(instance), seq).map_err(|fault| Self::not_wired("terminal command owner", format!("{}: {}", fault.code.0, fault.message)))?;
                let mut pending = self.pending_exchanges.remove(instance).expect("terminal pending exchange");
                self.await_response(instance, seq, &mut pending.response).map_err(|fault| Fault { code: fault.code, message: format!("{}; the acknowledging turn published {}", fault.message, named_shapes(&published)) })?;
                pending.response.take(seq).map(CommandTurn::Settled)
            }
            semio_framework::kernel::CommandBatchProgress::Faulted => {
                if let Some(pending) = self.pending_exchanges.get_mut(instance) {
                    if pending.ingress_fault.is_none() {
                        pending.ingress_fault = Some(ingress_fault_text(&turn.command_ingress));
                    }
                }
                self.pending_command_closes.begin_close(u64::from(instance), seq).map_err(|fault| Self::not_wired("faulted command owner", format!("{}: {}", fault.code.0, fault.message)))?;
                let (response_complete, _) = self.pending_exchanges.close_response_step(instance, semio_framework::kernel::COMMAND_PAGE_MAXIMUM_BYTES);
                if !response_complete {
                    return Ok(CommandTurn::MoreWork);
                }
                let (complete, _, _) = self.pending_command_closes.close_step(semio_framework::kernel::COMMAND_PAGE_MAXIMUM_BYTES);
                if complete {
                    let terminal = self.pending_exchanges.remove(instance).expect("faulted exchange reached an empty terminal owner");
                    assert!(terminal.response.terminal_is_empty(), "faulted pending response reached terminal empty");
                    Err(Self::not_wired("command ingress", format!("the guest refused seq {seq}: {}", terminal.ingress_fault.unwrap_or_else(|| "no reason reported".to_string()))))
                } else {
                    Ok(CommandTurn::MoreWork)
                }
            }
            semio_framework::kernel::CommandBatchProgress::PageReady | semio_framework::kernel::CommandBatchProgress::Waiting => Ok(CommandTurn::MoreWork),
        }
    }

    /// 📬️ Admits one effect, if it is THIS command's answer.
    ///
    /// 🧭️ **A command's answer is not an `Effect::Respond`.** The reactor publishes `Respond` for
    /// exactly one inbound event — `Event::Request`, the extension-capability seam
    /// (`⚛️reactor/🔄️turn/🦀️.rs`'s `inbound_request_effects`) — which this gateway never sends. A
    /// command's answer goes through `route_app_frame`, which addresses every non-`UiPatch`
    /// `AppFrame` to `Effect::SendMessage{target: Shell{instance}}` as encoded frame bytes,
    /// correlated by the frame's own `in_reply_to` against the COMMAND's `seq`. The React host reads
    /// exactly this lane (`🔌️PluginRuntime/🟦️.tsx`'s `shellFrameBytes`, "a `Shell{instance}`
    /// send-message IS an `AppFrame` reply"), which is why mutation verbs have always worked there
    /// and never here.
    ///
    /// 🐛️ Reading the respond lane meant the answer was *sitting in the same turn's effects*,
    /// unread: the guest drove ingress to `Complete`, published its frames, and went `Idle` — and the
    /// host reported "the guest acknowledged command seq 1 and then went idle without publishing a
    /// response for it" (ticket 26/09/18, WR1 §5.4 → WR2; measured: the acknowledging turn published
    /// `sendMessage(shell:0, Document(in_reply_to 1), 579 B)`).
    ///
    /// 🏁️ `AppFrame::Done` naming this seq is a reply STAMP, not an answer of its own. Every
    /// transaction route publishes its terminal frame AND a `Done` on the same turn
    /// (`🔌️plugin/🦀️.rs`'s `TransactionPrepare`/`Commit`/`Rollback` arms each push both), so
    /// admitting the second one reported "the guest published more than one frame answering seq
    /// N" for a guest that answered exactly once — measured 2026-09-20 the first time a real
    /// `TransactionPrepare` crossed the headless ingress. A `Done` still IS the answer for the
    /// verbs that publish nothing else (`LoadDocument`, `TransactionUndo`/`Redo`), which is why
    /// it is dropped only once a real frame is already held. A genuine duplicate — two answering
    /// frames neither of which is a stamp — stays as loud as WR2 made it.
    fn admit_reply_frame(pending: &mut PendingExchange, instance: u32, seq: u64, effect: &semio_framework::kernel::Effect) {
        let Some(payload) = shell_app_frame_payload(instance, effect) else {
            return;
        };
        let Ok(frame) = ::semio_framework_async::poll::resolve_ready(store::decode_app_frame(payload)) else {
            return;
        };
        if matches!(frame, store::AppFrame::Done { .. }) && pending.response.holds_frame() {
            return;
        }
        if app_frame_reply_seq(&frame) == Some(seq) || (app_frame_reply_seq(&frame).is_none() && app_frame_is_transaction_terminal(&frame)) {
            pending.response.admit_frame(payload);
        }
    }

    /// 📮️ Wakes the guest until it publishes the frame answering `seq`, once its command ingress has
    /// gone terminal.
    ///
    /// 🧭️ Acknowledging a command and ANSWERING it are two different events on this wire.
    /// `CommandBatchProgress::Complete` means the guest consumed every page and acknowledged the
    /// batch; the answer is a frame it publishes when the work is done — usually on the very turn
    /// that acknowledges, sometimes on a later one. Bounded by [`COMMAND_RESUME_WALL_BUDGET`].
    ///
    /// 🏁️ A settled command that published no frame naming itself is **not** a fault: it is a
    /// command whose verb has nothing to say, and the answer is a stamped `AppFrame::Done` — the
    /// same rule the React host applies (`commandIngressNeedsReplyStampV1`). Making it a fault here
    /// would refuse every `LoadDocument`/`TransactionUndo` the guest completed silently. What stays
    /// a fault is a guest that answers ANOTHER request, because that is a routing defect.
    ///
    /// 🛑️ A guest that is `Idle` with no wake pending has nothing left to do, so waiting the
    /// rest of the wall is pointless. A `Respond` under a request id this gateway never sent
    /// is the one shape that is still a defect worth naming.
    fn await_response(&mut self, instance: u32, seq: u64, response: &mut PendingResponsePage) -> Result<(), Fault> {
        let deadline = std::time::Instant::now() + COMMAND_RESUME_WALL_BUDGET;
        let mut foreign: Vec<u64> = Vec::new();
        while matches!(response, PendingResponsePage::Empty) {
            let runtime = Arc::clone(&self.runtime);
            let guest = self.instances.get_mut(&instance).ok_or_else(|| Self::not_wired("response", format!("no open instance {instance}")))?;
            let turn = match semio_framework_async::block_on(runtime.execute_turn(guest, std::slice::from_ref(&semio_framework::kernel::Event::Wake), headless_command_budget())) {
                Ok(turn) => turn,
                Err(error) => {
                    self.discard_instance(instance);
                    return Err(Self::not_wired("response", error));
                }
            };
            let idle = matches!(turn.status, semio_framework::kernel::TurnStatus::Idle) && turn.next_wake.is_none();
            for effect in &turn.effects {
                if let semio_framework::kernel::Effect::Respond { req, .. } = effect {
                    foreign.push(req.0);
                }
                let Some(payload) = shell_app_frame_payload(instance, effect) else {
                    continue;
                };
                let Ok(frame) = ::semio_framework_async::poll::resolve_ready(store::decode_app_frame(payload)) else {
                    continue;
                };
                if app_frame_reply_seq(&frame) == Some(seq) || (app_frame_reply_seq(&frame).is_none() && app_frame_is_transaction_terminal(&frame)) {
                    response.admit_frame(payload);
                }
            }
            if matches!(response, PendingResponsePage::Empty) && idle {
                if !foreign.is_empty() {
                    return Err(Fault { code: "channel.not-wired".to_string(), message: format!("the guest acknowledged command seq {seq} and answered request(s) {foreign:?} instead") });
                }
                response.stamp_settled();
                return Ok(());
            }
            if std::time::Instant::now() >= deadline {
                return Err(Self::budget_fault(&format!("the guest acknowledged command seq {seq} but published no response in")));
            }
        }
        Ok(())
    }
}

/// 🔢️ Every `AppCommand` variant's own leading `seq`, as a place to WRITE. The kernel envelope's
/// sequence and the command's own must be the same number: the guest answers a command by publishing
/// an `AppFrame` whose `in_reply_to` is the COMMAND's `seq` (never the envelope's), so a host that
/// mints an envelope sequence and leaves the command at a constant can never correlate the answer it
/// gets back. `🏃️run/🦀️.rs`'s `app_command_seq` reads the same field for the same reason, in the
/// other direction. Exhaustive on purpose: a new variant is a compile error, not a silent seq-of-zero.
#[cfg(not(target_arch = "wasm32"))]
fn app_command_seq_mut(command: &mut store::AppCommand) -> &mut u64 {
    match command {
        store::AppCommand::ConfigCommand { seq, .. }
        | store::AppCommand::Command { seq, .. }
        | store::AppCommand::CommandText { seq, .. }
        | store::AppCommand::ContextMenu { seq, .. }
        | store::AppCommand::LocalInteractionQuery { seq, .. }
        | store::AppCommand::ArtifactCommand { seq, .. }
        | store::AppCommand::ApplyEnvelopes { seq, .. }
        | store::AppCommand::LoadDocument { seq, .. }
        | store::AppCommand::ReadDocument { seq }
        | store::AppCommand::LoadDocumentArchive { seq, .. }
        | store::AppCommand::ReadDocumentArchive { seq }
        | store::AppCommand::PollDocumentArchiveLoad { seq, .. }
        | store::AppCommand::CancelDocumentArchiveLoad { seq, .. }
        | store::AppCommand::AcknowledgeDocumentArchiveLoad { seq, .. }
        | store::AppCommand::LoadConfig { seq, .. }
        | store::AppCommand::ReadConfig { seq }
        | store::AppCommand::LoadWindowConfig { seq, .. }
        | store::AppCommand::ReadWindowConfigs { seq }
        | store::AppCommand::MediaIn { seq, .. }
        | store::AppCommand::MediaOut { seq, .. }
        | store::AppCommand::MediaFingerprint { seq, .. }
        | store::AppCommand::PureCommand { seq, .. }
        | store::AppCommand::LoadChildren { seq, .. }
        | store::AppCommand::ReadChildren { seq }
        | store::AppCommand::ReadHistory { seq }
        | store::AppCommand::TransactionPrepare { seq, .. }
        | store::AppCommand::TransactionCommit { seq, .. }
        | store::AppCommand::TransactionRollback { seq, .. }
        | store::AppCommand::TransactionUndo { seq, .. }
        | store::AppCommand::TransactionRedo { seq, .. }
        | store::AppCommand::OpenArtifact { seq, .. }
        | store::AppCommand::SetDefaultApp { seq, .. }
        | store::AppCommand::ClearDefaultApp { seq, .. }
        | store::AppCommand::SetMergePolicy { seq, .. }
        | store::AppCommand::ResolveConflict { seq, .. }
        | store::AppCommand::ReadConflicts { seq }
        | store::AppCommand::Presence { seq, .. }
        | store::AppCommand::SubmitMediaExport { seq, .. }
        | store::AppCommand::PollMediaExport { seq, .. }
        | store::AppCommand::CancelMediaExport { seq, .. }
        | store::AppCommand::ReadDocumentIdentity { seq }
        | store::AppCommand::TakeMediaExportChunk { seq, .. } => seq,
    }
}

/// 📬️ Which command an `AppFrame` answers, when it answers one at all.
///
/// 🧭️ Three shapes, and the difference decides correlation. Most frames carry `in_reply_to: u64` and
/// name their command outright. `Error`/`MergeReport`/`Conflicts`/`UiPatch` carry
/// `in_reply_to: Option<u64>` because the same frame is also pushed unsolicited. The rest —
/// `DocumentChanged`, `Ephemeral`, `UiSnapshotEnd`, `OperationCompleted`, the three transaction
/// terminals — carry no reply sequence at all: the transaction trio correlates on its own `txn_id`
/// and the others are pushes. Exhaustive on purpose.
#[cfg(not(target_arch = "wasm32"))]
fn app_frame_reply_seq(frame: &store::AppFrame) -> Option<u64> {
    match frame {
        store::AppFrame::Done { in_reply_to }
        | store::AppFrame::Invocation { in_reply_to, .. }
        | store::AppFrame::Document { in_reply_to, .. }
        | store::AppFrame::Config { in_reply_to, .. }
        | store::AppFrame::WindowConfigs { in_reply_to, .. }
        | store::AppFrame::ContextMenu { in_reply_to, .. }
        | store::AppFrame::Media { in_reply_to, .. }
        | store::AppFrame::MediaFingerprint { in_reply_to, .. }
        | store::AppFrame::Emit { in_reply_to, .. }
        | store::AppFrame::Draft { in_reply_to, .. }
        | store::AppFrame::Children { in_reply_to, .. }
        | store::AppFrame::HistorySnapshot { in_reply_to, .. }
        | store::AppFrame::TransactionProposal { in_reply_to, .. }
        | store::AppFrame::DocumentArchive { in_reply_to, .. }
        | store::AppFrame::DocumentArchiveLoad { in_reply_to, .. }
        | store::AppFrame::MediaExportSubmitted { in_reply_to, .. }
        | store::AppFrame::MediaExportStatus { in_reply_to, .. }
        | store::AppFrame::DocumentIdentity { in_reply_to, .. }
        | store::AppFrame::MediaExportChunk { in_reply_to, .. } => Some(*in_reply_to),
        store::AppFrame::Error { in_reply_to, .. } | store::AppFrame::MergeReport { in_reply_to, .. } | store::AppFrame::Conflicts { in_reply_to, .. } | store::AppFrame::UiPatch { in_reply_to, .. } => *in_reply_to,
        store::AppFrame::DocumentChanged { .. }
        | store::AppFrame::ConfigChanged { .. }
        | store::AppFrame::Ephemeral { .. }
        | store::AppFrame::TransactionPrepared { .. }
        | store::AppFrame::TransactionCommitted { .. }
        | store::AppFrame::TransactionRolledBack { .. }
        | store::AppFrame::UiSnapshotEnd { .. }
        | store::AppFrame::OperationCompleted { .. }
        | store::AppFrame::LocalInteractionQuery { .. } => None,
    }
}

/// 📬️ Whether a frame with no `in_reply_to` is still THIS command's terminal answer. The three
/// transaction terminals are: `transaction_prepare`/`commit`/`rollback` are answered by
/// `TransactionPrepared`/`TransactionCommitted`/`TransactionRolledBack`, which correlate on the
/// `txn_id` the caller itself sent (and which the caller's own arm checks) rather than on a
/// sequence. Everything else without a reply sequence is an unsolicited push and is never an answer.
#[cfg(not(target_arch = "wasm32"))]
fn app_frame_is_transaction_terminal(frame: &store::AppFrame) -> bool {
    matches!(frame, store::AppFrame::TransactionPrepared { .. } | store::AppFrame::TransactionCommitted { .. } | store::AppFrame::TransactionRolledBack { .. })
}

/// 📬️ One frame's variant name, for a fault that has to say what came back without quoting a
/// guest's bytes.
#[cfg(not(target_arch = "wasm32"))]
fn app_frame_tag(frame: &store::AppFrame) -> &'static str {
    match frame {
        store::AppFrame::Done { .. } => "Done",
        store::AppFrame::Invocation { .. } => "Invocation",
        store::AppFrame::DocumentChanged { .. } => "DocumentChanged",
        store::AppFrame::Document { .. } => "Document",
        store::AppFrame::Config { .. } => "Config",
        store::AppFrame::WindowConfigs { .. } => "WindowConfigs",
        store::AppFrame::ConfigChanged { .. } => "ConfigChanged",
        store::AppFrame::ContextMenu { .. } => "ContextMenu",
        store::AppFrame::Media { .. } => "Media",
        store::AppFrame::MediaFingerprint { .. } => "MediaFingerprint",
        store::AppFrame::Error { .. } => "Error",
        store::AppFrame::Emit { .. } => "Emit",
        store::AppFrame::Draft { .. } => "Draft",
        store::AppFrame::Children { .. } => "Children",
        store::AppFrame::Ephemeral { .. } => "Ephemeral",
        store::AppFrame::HistorySnapshot { .. } => "HistorySnapshot",
        store::AppFrame::TransactionProposal { .. } => "TransactionProposal",
        store::AppFrame::TransactionPrepared { .. } => "TransactionPrepared",
        store::AppFrame::TransactionCommitted { .. } => "TransactionCommitted",
        store::AppFrame::TransactionRolledBack { .. } => "TransactionRolledBack",
        store::AppFrame::MergeReport { .. } => "MergeReport",
        store::AppFrame::Conflicts { .. } => "Conflicts",
        store::AppFrame::UiPatch { .. } => "UiPatch",
        store::AppFrame::UiSnapshotEnd { .. } => "UiSnapshotEnd",
        store::AppFrame::OperationCompleted { .. } => "OperationCompleted",
        store::AppFrame::LocalInteractionQuery { .. } => "LocalInteractionQuery",
        store::AppFrame::DocumentIdentity { .. } => "DocumentIdentity",
        store::AppFrame::DocumentArchive { .. } => "DocumentArchive",
        store::AppFrame::DocumentArchiveLoad { .. } => "DocumentArchiveLoad",
        store::AppFrame::MediaExportSubmitted { .. } => "MediaExportSubmitted",
        store::AppFrame::MediaExportStatus { .. } => "MediaExportStatus",
        store::AppFrame::MediaExportChunk { .. } => "MediaExportChunk",
    }
}

/// 🧾️ The guest's own reason for refusing a command's ingress, read off the turn that reported it.
/// The reactor mints these two ways — a real `Fault` encoded through `dsl::encode_fault_bytes`, and
/// a handful of bare ASCII codes for the structural refusals (`plugin.command-page-invalid`,
/// `plugin.command-cancelled-by-close`, …) — so both are decoded, in that order, and neither is
/// ever silently dropped.
#[cfg(not(target_arch = "wasm32"))]
fn ingress_fault_text(status: &semio_framework::kernel::CommandIngressStatus) -> String {
    let semio_framework::kernel::CommandIngressStatus::Fault { fault, .. } = status else {
        return format!("the driver reported a fault while the guest reported {status:?}");
    };
    if let Ok(text) = std::str::from_utf8(fault) {
        if !text.is_empty() && text.chars().all(|character| character.is_ascii_graphic() || character == ' ') {
            return text.to_string();
        }
    }
    let decoded = decode_guest_fault(fault);
    format!("{}: {}", decoded.code, decoded.message)
}

/// 📨️ The `AppFrame` bytes one `Shell{instance}` send-message carries, or `None` when the effect is
/// not an app-frame message addressed at this instance. The endpoint carries three languages — a
/// command's answer and an interactive job's result page/ack — so the two job languages are told
/// apart by their own magic prefix rather than by a failed decode.
#[cfg(not(target_arch = "wasm32"))]
fn shell_app_frame_payload(instance: u32, effect: &semio_framework::kernel::Effect) -> Option<&[u8]> {
    let semio_framework::kernel::Effect::SendMessage { target: semio_framework::kernel::MessageEndpoint::Shell { instance: addressed }, payload } = effect else {
        return None;
    };
    if addressed.0 != instance.to_string() || payload.starts_with(TYPED_OPERATION_PAGE_MAGIC) || payload.starts_with(TYPED_OPERATION_ACK_MAGIC) {
        return None;
    }
    Some(payload.as_slice())
}

/// 🧵️ One effect's document-backbone payload, when it is one addressed at `actor_label` — the guest's
/// own `BackboneMessage::Mutations` bytes on their way to the document actor. The uri check is the
/// same ownership fence `route_document_backbone_effects` applies in the wgpu shell: a guest that
/// addresses another actor's backbone is publishing into a document this channel does not own, and
/// its bytes must not be relayed as if it did.
#[cfg(not(target_arch = "wasm32"))]
fn document_backbone_payload<'a>(actor_label: &str, effect: &'a semio_framework::kernel::Effect) -> Option<&'a [u8]> {
    let semio_framework::kernel::Effect::SendMessage { target: semio_framework::kernel::MessageEndpoint::Backbone { uri }, payload } = effect else {
        return None;
    };
    (uri == actor_label).then(|| payload.as_slice())
}

/// 🧯️ The refusal a guest answered on `instance`'s shell lane, if `effect` is one: an `AppFrame::Error`
/// that is neither a typed-operation page nor an acknowledgement.
#[cfg(not(target_arch = "wasm32"))]
fn shell_lane_fault(instance: u32, effect: &semio_framework::kernel::Effect) -> Option<Fault> {
    let semio_framework::kernel::Effect::SendMessage { target: semio_framework::kernel::MessageEndpoint::Shell { instance: addressed }, payload } = effect else {
        return None;
    };
    if addressed.0 != instance.to_string() || payload.starts_with(TYPED_OPERATION_PAGE_MAGIC) || payload.starts_with(TYPED_OPERATION_ACK_MAGIC) {
        return None;
    }
    match ::semio_framework_async::poll::resolve_ready(store::decode_app_frame(payload)) {
        Ok(store::AppFrame::Error { fault, .. }) => Some(decode_guest_fault(&fault)),
        _ => None,
    }
}

/// 🧾️ One effect named by SHAPE, never by payload — what a fault says the guest published instead
/// of the answer it owed. A shell message is named with the instance it addresses, because
/// "addressed at another instance" and "addressed at this one but unreadable" are different defects
/// and a fault that collapses them costs the next reader the measurement all over again.
#[cfg(not(target_arch = "wasm32"))]
fn effect_shape(instance: u32, effect: &semio_framework::kernel::Effect) -> String {
    match effect {
        semio_framework::kernel::Effect::SendMessage { target: semio_framework::kernel::MessageEndpoint::Shell { instance: addressed }, payload } => {
            let lane = if payload.starts_with(TYPED_OPERATION_PAGE_MAGIC) {
                "typed-operation-page".to_string()
            } else if payload.starts_with(TYPED_OPERATION_ACK_MAGIC) {
                "typed-operation-ack".to_string()
            } else {
                match ::semio_framework_async::poll::resolve_ready(store::decode_app_frame(payload)) {
                    Ok(frame) => match app_frame_reply_seq(&frame) {
                        Some(reply) => format!("{}(in_reply_to {reply})", app_frame_tag(&frame)),
                        None => format!("{}(unsolicited)", app_frame_tag(&frame)),
                    },
                    Err(error) => format!("undecodable app-frame ({error})"),
                }
            };
            let mine = addressed.0 == instance.to_string();
            format!("sendMessage(shell:{}{}, {lane}, {} B)", addressed.0, if mine { "" } else { " — NOT this instance" }, payload.len())
        }
        semio_framework::kernel::Effect::SendMessage { target, .. } => format!("sendMessage({target:?})"),
        semio_framework::kernel::Effect::Respond { req, .. } => format!("respond(req {})", req.0),
        semio_framework::kernel::Effect::PublishEvent { topic, .. } => format!("publishEvent({topic})"),
        other => format!("{}", EffectTag(other)),
    }
}

/// 🧾️ A `Debug` rendering cut at its variant name — the payload of an effect is a guest's bytes and
/// has no place in an agent-facing fault.
#[cfg(not(target_arch = "wasm32"))]
struct EffectTag<'a>(&'a semio_framework::kernel::Effect);

#[cfg(not(target_arch = "wasm32"))]
impl std::fmt::Display for EffectTag<'_> {
    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        let rendered = format!("{:?}", self.0);
        let head: String = rendered.chars().take_while(|character| character.is_alphanumeric()).collect();
        formatter.write_str(if head.is_empty() { "effect" } else { &head })
    }
}

/// 🧾️ The shapes above, joined — or an explicit "nothing", because an empty list in a fault message
/// reads as a truncation rather than as a measurement.
#[cfg(not(target_arch = "wasm32"))]
fn named_shapes(shapes: &[String]) -> String {
    if shapes.is_empty() {
        "no effects at all".to_string()
    } else {
        shapes.join(", ")
    }
}

/// 📨️ The two non-`AppFrame` languages that ride the SAME `Shell{instance}` endpoint
/// (`🔌️plugin/🦀️.rs`'s `TypedOperationResultPage::{RENDERER_PAGE_MAGIC, RENDERER_ACK_MAGIC}`), so a
/// reader of this endpoint tells a command's answer from an interactive job's result page by prefix
/// rather than by a failed decode. Two banks, one literal: the renderer's own copy is
/// `🎭️actor/🖼️wire-turn/🟦️.ts`'s `TYPED_OPERATION_PAGE_MAGIC`/`TYPED_OPERATION_ACK_MAGIC`. This crate
/// does not depend on `🔌️plugin` (see its Cargo.toml), which is why the bytes are restated here.
#[cfg(not(target_arch = "wasm32"))]
const TYPED_OPERATION_PAGE_MAGIC: &[u8] = b"semio.typed-operation-page.v1\0";
#[cfg(not(target_arch = "wasm32"))]
const TYPED_OPERATION_ACK_MAGIC: &[u8] = b"semio.typed-operation-ack.v1\0";

/// 🔁️ What one `exchange_one_turn` produced: the command's terminal frame, or an honest "this
/// command owes another turn". Keeping these apart from `Fault` is what lets the loop above bound
/// the NUMBER of turns without having to read a fault's code to decide whether to continue.
#[cfg(not(target_arch = "wasm32"))]
enum CommandTurn {
    Settled(store::AppFrame),
    MoreWork,
}

/// 🛂️ Whether this process may submit a command envelope into a guest's paged ingress at all — the
/// same predicate `📺️renderer/…/🧊️wgpu/🧊️renderer` (the live, shipping consumer of the identical
/// `CommandBatchDriver`/`FixedCommandPage` machinery) asks over the identical kernel constants:
/// there must be at least one page, and one whole page must fit inside a command's total byte
/// budget. A hardcoded `false` here made EVERY `AppCommand` this gateway ever built answer
/// `AppCommand not wired` before it reached a guest, which is why no `action_prepare`/`action_invoke`
/// from a real MCP client could ever reach a plugin (ticket 26/09/18 slice A1).
#[cfg(not(target_arch = "wasm32"))]
fn persistent_command_completion_port_ready() -> bool {
    semio_framework::kernel::COMMAND_MAXIMUM_PAGES != 0 && semio_framework::kernel::COMMAND_MAXIMUM_BYTES >= semio_framework::kernel::COMMAND_PAGE_MAXIMUM_BYTES
}

/// 🧯️ Best-effort decode of a real guest `AppFrame::Error`/`TransactionPrepared.rejection` fault
/// blob into this port's own `Fault{code,message}` — the wire's real fault type
/// (`🔌️plugin::Fault`, wrapping `FaultOrigin`/`FaultCode`) is private to that crate (not reachable
/// from here), so this decodes the SAME `store::pack_rt`/`DslValue` wire envelope every real fault
/// travels over generically, as a `DslValue`, and reads `code`/`message` defensively —
/// never panics, never invents a code the guest did not send.
#[cfg(not(target_arch = "wasm32"))]
fn decode_guest_fault(bytes: &[u8]) -> Fault {
    let decoded = store::pack_rt::decode_wire_value(bytes).ok();
    match decoded {
        Some(value) => {
            let code = value.get("code").and_then(store::DslValue::as_str).unwrap_or("app.command.rejected").to_string();
            let message = value.get("message").and_then(store::DslValue::as_str).map(str::to_string).unwrap_or_else(|| semio_framework_pack_json::to_json_string(&value));
            Fault { code, message }
        }
        None => Fault { code: "app.command.rejected".to_string(), message: format!("guest rejected the command ({} bytes of fault detail, undecodable as JSON)", bytes.len()) },
    }
}

/// 📤️ Splits one wire ops-pack blob into this port's own `Vec<Vec<u8>>` lane shape — **one element
/// per complete op payload**, which is `PreparedOps`' own documented contract (`🔀️dispatch/🦀️.rs`:
/// "one element per complete op payload, never a single stream").
///
/// 🐛️ This used to hand the whole `encode_ops_vec` blob back as ONE opaque element, on the stated
/// assumption that "`TransactionPrepare`'s pre-planned form re-forwards the SAME bytes verbatim, so
/// the framing only has to round-trip through this one port, never be individually addressed". The
/// assumption is false and became measurable the moment WR3's paged routes let a real
/// `TransactionPrepare` reach a real guest: `VcsArtifactApp::transaction_prepare` runs
/// `A::Mutation::decode_op(op_bytes)` over EVERY element, so a whole ops-vec envelope handed in as
/// one element decodes as no mutation at all. It also made an EMPTY lane non-empty — `encode_ops_vec`
/// of nothing is a one-byte zero count, which became `[[0]]` — and `PluginArtifactChannel`'s own
/// `TransactionPrepare` arm refuses any prepare whose config/draft lane is non-empty, so every
/// two-phase invoke would have been refused for carrying config ops it never emitted.
#[cfg(not(target_arch = "wasm32"))]
fn ops_pack_lane(bytes: Vec<u8>) -> Result<Vec<Vec<u8>>, Fault> {
    if bytes.is_empty() {
        return Ok(Vec::new());
    }
    store::causal::decode_ops_vec(&bytes).map_err(|error| PluginArtifactChannel::not_wired("decoding the guest's emitted ops", format!("{error:?}")))
}

/// 📤️ Every OUT port one editor app can actually be exported through, in the order an export picks
/// them.
///
/// 🧭️ Measured across every committed descriptor in the repo (2026-09-20): `AppDefinition
/// .media_outputs` is **empty for all 35 plugins**. An app's real OUT ports live in
/// `AppIo.ports` with `direction: out` (`writer: text:out`, `lowpoly: mesh:out`, `draw:
/// vector:out`, …), and the builder method that fills `media_outputs` has no caller anywhere.
/// Reading only `media_outputs` is therefore why `artifact_export` answered
/// `declaredExportFormats: []` for a plugin that exports for real
/// (`📓️wr2-headless-command-response-wire.md` §7.2).
///
/// 🗿️ `artifact:out` closes the list rather than opening it: `AppIo::all_ports` gives every app that
/// implicit port and `ArtifactEditor::export_media`'s provided body answers it with the document's
/// own pack, so it is a real declared surface — but an app-specific port is the better answer when
/// one exists, and an export with no requested format takes the first.
#[cfg(not(target_arch = "wasm32"))]
fn app_media_out_ports(app: &semio_framework::AppDefinition) -> Vec<String> {
    let mut ports: Vec<String> = app
        .media_outputs
        .iter()
        .chain(app.io.ports.iter())
        .filter(|port| port.direction == semio_framework::MediaPortDirection::Out)
        .map(|port| port.id.clone())
        .collect();
    ports.push("artifact:out".to_string());
    let mut seen: std::collections::BTreeSet<String> = std::collections::BTreeSet::new();
    ports.retain(|port| seen.insert(port.clone()));
    ports
}

/// 🔗️ Folds the artifact this inference is being run ON into the canonical request body, under the
/// field the inference's OWN published contract names.
///
/// 🧭️ Declared, never invented. The host writes exactly `InferenceArtifactBinding.field`, in exactly
/// `InferenceArtifactBinding.encoding`, and refuses by name in every other case: an unpublished
/// contract, an encoding this host has no writer for, or a required binding with no artifact named.
/// Before this existed an agent could only ever send `{}` — `inference_run`'s tool schema had no
/// artifact at all — and the guest answered `missing field 'snapshot'` after the whole component had
/// been compiled and dispatched (`📓️pz2-puzzle-describe-under-budget.md` §5.2).
///
/// ✍️ A caller that supplies the bound field itself keeps it: the binding fills a GAP, it never
/// overwrites a body the caller authored.
///
/// 📦️ The one shape `INFERENCE_ARTIFACT_PACK_BASE64` names, written with the same standard
/// alphabet the guest's `ArtifactDocumentPayload::pair()` decodes with. The gateway does not
/// link the guest SDK (`🌉️mcp` depends on the plugin HOST, never on the plugin crate), so
/// the encoding constant is the contract between the two halves, not a shared type.
///
/// 🧭️ `required` means "this inference needs SOME body and the caller cannot type one", not
/// "this field or nothing": a published contract may offer a second carrier (`🀄️wfc`'s own
/// request schema is `oneOf [document, snapshot]`), and a caller who stated one has already
/// answered the requirement. Refusing an authored body here made a hand-written `snapshot`
/// unroutable (measured 2026-09-22 21:2x) — the guest, which owns the schema, is the judge
/// of a body that exists; this gateway only refuses an EMPTY one.
#[cfg(not(target_arch = "wasm32"))]
fn bind_inference_document(declared: &semio_framework::ContributedInferenceMetadata, command: &crate::actions::InferCommand) -> Result<Vec<u8>, Fault> {
    let Some(binding) = declared.payload.as_ref().and_then(|contract| contract.artifact_binding.as_ref()) else {
        return Ok(command.canonical_payload.clone());
    };
    if binding.encoding != semio_framework::INFERENCE_ARTIFACT_PACK_BASE64 {
        return Err(Fault {
            code: "app.command.rejected".to_string(),
            message: format!("`{}` declares artifact binding encoding `{}`, which this gateway has no writer for (it writes `{}`)", declared.inference_schema, binding.encoding, semio_framework::INFERENCE_ARTIFACT_PACK_BASE64),
        });
    }
    let mut body: serde_json::Value = if command.canonical_payload.is_empty() {
        serde_json::json!({})
    } else {
        serde_json::from_slice(&command.canonical_payload).map_err(|error| Fault { code: "app.command.rejected".to_string(), message: format!("`{}` payload is not a JSON object: {error}", declared.inference_schema) })?
    };
    let Some(object) = body.as_object_mut() else {
        return Err(Fault { code: "app.command.rejected".to_string(), message: format!("`{}` payload is not a JSON object", declared.inference_schema) });
    };
    if object.contains_key(&binding.field) {
        return serde_json::to_vec(&body).map_err(|error| Fault { code: "plugin.internal".to_string(), message: format!("encoding the inference payload: {error}") });
    }
    match command.artifact_document.as_ref() {
        Some(document) => {
            object.insert(binding.field.clone(), serde_json::json!({ "pack": crate::shell_channel::encode_base64(&document.pack), "spr": crate::shell_channel::encode_base64(&document.spr) }));
        }
        None if binding.required && object.is_empty() => {
            return Err(Fault {
                code: "app.command.rejected".to_string(),
                message: format!("`{}` is artifact-bound: name the artifact to run it on with `artifactId`, or supply `payload.{}` yourself", declared.inference_schema, binding.field),
            })
        }
        None => {}
    }
    serde_json::to_vec(&body).map_err(|error| Fault { code: "plugin.internal".to_string(), message: format!("encoding the inference payload: {error}") })
}

#[cfg(not(target_arch = "wasm32"))]
impl ArtifactChannel for PluginArtifactChannel {
    /// 💡️ `Infer` never touches the retained command-page lane, so it must not be gated on the
    /// command-lane instance being open at all: it drives its own guest instance, on its own actor
    /// ordinal, opened on first use by `ensure_inference_route`.
    ///
    /// 🔭️ The head is the newest APPLIED entry, not the newest entry.
    /// `HistoryPatch.upserts` is ordered newest-first and an undo does not
    /// remove its row — it clears `HistoryEntry.applied` — so reading
    /// `upserts.first()` reported the identical stamp before and after
    /// `history.undo`, and `expectedRevision` (the ONLY revision oracle an agent
    /// has for a plugin-owned artifact) could not express that a change had been
    /// walked back. Measured 2026-09-20 22:38 on a real `🗒️note` guest: an
    /// `addBlock` committed, undone and redone stamped `transaction:txn_…/1`
    /// throughout, so an optimistic-concurrency client would have re-committed
    /// over an undo without ever seeing a `REVISION_CONFLICT`.
    ///
    /// 🧮️ PHASE ONE of the agent lane's two-phase contract: the guest validates, prices
    /// and produces the ops WITHOUT applying any of them (`VcsArtifactApp::
    /// preview_addressed_action`, whose own doc carries the soundness argument). The
    /// frame is the SAME owner-qualified `ManifestActionInvocation` the shell's UI lane
    /// sends on `AppCommand::Command` — one dispatch shape for both lanes — built here
    /// from the plugin's own committed manifest, never parsed out of the capability id.
    /// It used to be `{"capabilityId":…,"input":…}`, an opaque blob no guest could select
    /// a command-specific pre-serde envelope from, which is exactly what the guest's
    /// three-line refusal said (`interactive-job.missing-exact-key`).
    ///
    /// 🚧️ Same honesty rule: real wire call, real answer. The wire's `TransactionPrepare`
    /// carries ONE flat `prepared_ops` list (document lane only — `transaction_prepare`'s
    /// own signature has no config/draft parameter); a config/draft-lane prepare has no
    /// wire representation yet, reported as such rather than silently dropped.
    ///
    /// 🚧️ `origin` is this port's own invented `MutationOrigin::Agent` shape — the
    /// real wire `os_spr::MutationOrigin` has exactly three variants
    /// (`Owner`/`Contributed`/`Transaction`), none of which represent "an agent
    /// principal invoked this headlessly"; sending empty bytes decodes as `None`
    /// (asserting no origin) rather than fabricating a wire shape that does not exist.
    ///
    /// ✅️ Real and fully generic: `TransactionCommit`/`Rollback`/`Undo`/`Redo` need only
    /// `txn_id`/`group_id` — no plugin-specific payload, so (unlike `PureCommand`/
    /// `TransactionPrepare`) these genuinely work against any real committed transaction.
    ///
    /// ✅️ Real and general: every plugin-declared inference service, not just the one
    /// hub-backed GIS Map job. Routed through `ArtifactInferenceRouter` exactly the way
    /// `🏃️run`'s own plugin reactor routes `job_infer`, so the guest's result is the
    /// guest's own — this arm fabricates nothing and short-circuits nothing.
    ///
    /// 📤️ Real and general: the artifact's own pack bytes go in with `LoadDocument`, then
    /// the app's own OUT port is read with `MediaOut` — the identical pair `🏃️run`'s
    /// workflow executor drives per node (`🏃️run/🦀️.rs`'s `compute_node`). Nothing about
    /// the exported bytes is interpreted here: `descriptor`/`data` are the guest's own.
    ///
    /// 🆕️ The guest's own genesis document, straight off `ReadDocument` — host-opaque
    /// bytes this crate persists verbatim under the plugin's real schema id, which is how
    /// `artifact_create{kind}` produces a plugin-typed artifact without this host ever
    /// owning a plugin's document type.
    fn exchange(&mut self, instance: u32, commands: Vec<AppCommand>) -> Result<Vec<AppFrame>, Fault> {
        if commands.len() != 1 {
            return Err(Self::not_wired("exchange", format!("expected exactly one command, received {}", commands.len())));
        }
        if !matches!(commands.first(), Some(AppCommand::Infer(_))) {
            self.ensure_instance(instance)?;
        }
        let mut frames = Vec::with_capacity(commands.len());
        for command in commands {
            let frame = match command {
                AppCommand::ReadHistory => match self.exchange_one_real(instance, store::AppCommand::ReadHistory { seq: 0 })? {
                    store::AppFrame::HistorySnapshot { history_patch, .. } => {
                        let value = store::pack_rt::decode_wire_value(&history_patch).map_err(|error| Self::not_wired("decoding HistoryPatch", error))?;
                        let patch: semio_framework::kernel::HistoryPatch = semio_framework_value::FromValue::from_value(value).map_err(|error| Self::not_wired("decoding HistoryPatch", error))?;
                        AppFrame::HistorySnapshot(RevisionStamp {
                            artifact_id: self.stamped_artifact_id(),
                            head_edit_id: patch.upserts.iter().find(|entry| entry.applied).map(|entry| entry.action_id.clone()).unwrap_or_default(),
                            cursor: patch.cursor.to_string(),
                        })
                    }
                    other => return Err(Self::not_wired("ReadHistory", format!("unexpected real AppFrame variant {other:?}"))),
                },
                AppCommand::PureCommand { capability_id, input } => {
                    let invocation = self.addressed_action_invocation(&capability_id, &input)?;
                    let command = store::pack_rt::encode_wire_value(&store::ToValue::to_value(&invocation));
                    match self.exchange_one_real(
                        instance,
                        store::AppCommand::PureCommand { seq: 0, command, document: Vec::new(), document_spr: Vec::new(), config: Vec::new(), config_spr: Vec::new(), draft: Vec::new(), draft_spr: Vec::new() },
                    )? {
                        store::AppFrame::Emit { document_ops, config_ops, draft_ops, child_ops, .. } => {
                            let (ops, warnings) = headless_agent_ops(&capability_id, PreparedOps { document: ops_pack_lane(document_ops)?, config: ops_pack_lane(config_ops)?, draft: ops_pack_lane(draft_ops)?, children: child_ops })?;
                            AppFrame::Emit { ops, warnings }
                        }
                        store::AppFrame::Error { fault, .. } => return Err(decode_guest_fault(&fault)),
                        other => return Err(Self::not_wired("PureCommand", format!("unexpected real AppFrame variant {other:?}"))),
                    }
                }
                AppCommand::TransactionPrepare { txn_id, ops, label, origin: _origin } => {
                    if !ops.config.is_empty() || !ops.draft.is_empty() {
                        return Err(Self::not_wired("TransactionPrepare", "a headless agent's transaction carries document operations only; its preview (`headless_agent_ops`) already kept config/draft view state in the shell"));
                    }
                    match self.exchange_one_real(
                        instance,
                        store::AppCommand::TransactionPrepare { seq: 0, txn_id: txn_id.clone(), mutation_id: String::new(), payload: Vec::new(), prepared_ops: ops.document, label, origin: Vec::new(), prepared_child_ops: ops.children },
                    )? {
                        store::AppFrame::TransactionPrepared { txn_id, rejection, .. } if rejection.is_empty() => AppFrame::TransactionPrepared { txn_id },
                        store::AppFrame::TransactionPrepared { rejection, .. } => return Err(decode_guest_fault(&rejection)),
                        store::AppFrame::Error { fault, .. } => return Err(decode_guest_fault(&fault)),
                        other => return Err(Self::not_wired("TransactionPrepare", format!("unexpected real AppFrame variant {other:?}"))),
                    }
                }
                AppCommand::TransactionCommit { txn_id } => match self.exchange_one_real(instance, store::AppCommand::TransactionCommit { seq: 0, txn_id: txn_id.clone() })? {
                    store::AppFrame::TransactionCommitted { txn_id, edit_id } => AppFrame::TransactionCommitted { txn_id, edit_id, relay: None },
                    store::AppFrame::Error { fault, .. } => return Err(decode_guest_fault(&fault)),
                    other => return Err(Self::not_wired("TransactionCommit", format!("unexpected real AppFrame variant {other:?}"))),
                },
                AppCommand::TransactionRollback { txn_id } => match self.exchange_one_real(instance, store::AppCommand::TransactionRollback { seq: 0, txn_id: txn_id.clone() })? {
                    store::AppFrame::TransactionRolledBack { txn_id } => AppFrame::TransactionRolledBack { txn_id },
                    store::AppFrame::Error { fault, .. } => return Err(decode_guest_fault(&fault)),
                    other => return Err(Self::not_wired("TransactionRollback", format!("unexpected real AppFrame variant {other:?}"))),
                },
                AppCommand::TransactionUndo { group_id } => match self.exchange_one_real(instance, store::AppCommand::TransactionUndo { seq: 0, group_id: group_id.clone() })? {
                    store::AppFrame::Done { .. } => AppFrame::TransactionUndone { group_id },
                    store::AppFrame::Error { fault, .. } => return Err(decode_guest_fault(&fault)),
                    other => return Err(Self::not_wired("TransactionUndo", format!("unexpected real AppFrame variant {other:?}"))),
                },
                AppCommand::Infer(command) => {
                    let result = self.infer_real(&command)?;
                    AppFrame::Inferred { inference_schema: result.inference_schema, complete: result.complete, payload: result.canonical_payload }
                }
                AppCommand::TransactionRedo { group_id } => match self.exchange_one_real(instance, store::AppCommand::TransactionRedo { seq: 0, group_id: group_id.clone() })? {
                    store::AppFrame::Done { .. } => AppFrame::TransactionRedone { group_id },
                    store::AppFrame::Error { fault, .. } => return Err(decode_guest_fault(&fault)),
                    other => return Err(Self::not_wired("TransactionRedo", format!("unexpected real AppFrame variant {other:?}"))),
                },
                AppCommand::ExportMedia { port, document, document_spr } => {
                    match self.exchange_one_real(instance, store::AppCommand::LoadDocument { seq: 0, pack: document, spr: document_spr })? {
                        store::AppFrame::Done { .. } => {}
                        store::AppFrame::Error { fault, .. } => return Err(decode_guest_fault(&fault)),
                        other => return Err(Self::not_wired("ExportMedia/LoadDocument", format!("unexpected real AppFrame variant {other:?}"))),
                    }
                    match self.exchange_one_real(instance, store::AppCommand::MediaOut { seq: 0, port: port.clone(), request: Vec::new() })? {
                        store::AppFrame::Media { port, descriptor, data, .. } => AppFrame::Exported { port, descriptor, data },
                        store::AppFrame::Error { fault, .. } => return Err(decode_guest_fault(&fault)),
                        other => return Err(Self::not_wired("ExportMedia/MediaOut", format!("unexpected real AppFrame variant {other:?}"))),
                    }
                }
                AppCommand::ReadArtifact => match self.exchange_one_real(instance, store::AppCommand::ReadDocument { seq: 0 })? {
                    store::AppFrame::Document { pack, spr, .. } => AppFrame::Artifact { pack, spr },
                    store::AppFrame::Error { fault, .. } => return Err(decode_guest_fault(&fault)),
                    other => return Err(Self::not_wired("ReadArtifact", format!("unexpected real AppFrame variant {other:?}"))),
                },
            };
            frames.push(frame);
        }
        Ok(frames)
    }

    fn activate(&mut self, instance: u32, scope: &ActivationScope) -> Result<(), Fault> {
        self.ensure_instance_scoped(instance, scope)
    }
}

//#region 🔖️Routing
/// 🧭️ `plugin_id` for every catalog entry `CapabilityOwner::Plugin{..}` names, deduplicated and
/// sorted — doubles as a stable, catalog-derived NUMBERING (`plugin_instance_slot`/
/// `plugin_for_instance_slot` below), not just a set: `ActionAdapter::prepare` issues a bare
/// `AppCommand::ReadHistory` (no capability id at all) BEFORE the `PureCommand` that names one
/// (`🔀️dispatch/🦀️.rs`'s own `prepare`), so `RoutingArtifactChannel::exchange` cannot always
/// read a capability id off the wire — it needs `instance` itself to already encode the plugin, which
/// only works if every caller derives `instance` from the SAME deterministic function of the catalog.
#[cfg(not(target_arch = "wasm32"))]
fn distinct_plugin_ids(catalog: &Catalog) -> Vec<String> {
    let set: std::collections::BTreeSet<String> = catalog.entries.iter().filter_map(|entry| match &entry.owner { CapabilityOwner::Plugin { plugin_id, .. } => Some(plugin_id.clone()), _ => None }).collect();
    set.into_iter().collect()
}

/// 🪪️ One guest the headless lane routes to: one app of one plugin. A plugin declares several apps
/// when it owns several artifact kinds (`block`: 2d/3d/5d, `wfc`: bitmap/grid2d/grid3d/…), and a
/// guest instance hosts exactly one app, so a verb of `s.block.block3d@1/*#editor` must reach an
/// instance of THAT app. `app_id: None` is a plugin-scope capability (no app of its own), which
/// runs on the plugin's first editor app.
#[cfg(not(target_arch = "wasm32"))]
#[derive(Clone, Debug, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub struct AppRoute {
    pub plugin_id: String,
    pub app_id: Option<String>,
}

/// 🧭️ Every route the catalog's plugin capabilities name plus each plugin's own default route,
/// deduplicated and sorted — the stable, catalog-derived NUMBERING [`route_slot`]/[`route_for_slot`]
/// encode `instance` with: a capability-less command (`ReadHistory`, `TransactionCommit`) must decode
/// its route from `instance` alone.
#[cfg(not(target_arch = "wasm32"))]
fn distinct_routes(catalog: &Catalog) -> Vec<AppRoute> {
    let set: std::collections::BTreeSet<AppRoute> = catalog
        .entries
        .iter()
        .filter_map(|entry| match &entry.owner {
            CapabilityOwner::Plugin { plugin_id, app_id, .. } => Some([AppRoute { plugin_id: plugin_id.clone(), app_id: None }, AppRoute { plugin_id: plugin_id.clone(), app_id: app_id.clone() }]),
            _ => None,
        })
        .flatten()
        .collect();
    set.into_iter().collect()
}

/// 🔢️ The slot of `plugin_id`'s default route (its first editor app).
#[cfg(not(target_arch = "wasm32"))]
fn plugin_instance_slot(catalog: &Catalog, plugin_id: &str) -> Option<u32> {
    route_slot(catalog, &AppRoute { plugin_id: plugin_id.to_string(), app_id: None })
}

/// 🔢️ `route`'s position in [`distinct_routes`] — the `instance` every command of one call's sequence
/// carries, so it decodes back to the same app via [`route_for_slot`] with no shared mutable state.
#[cfg(not(target_arch = "wasm32"))]
fn route_slot(catalog: &Catalog, route: &AppRoute) -> Option<u32> {
    distinct_routes(catalog).iter().position(|candidate| candidate == route).map(|index| index as u32)
}

/// 🔢️ The instance slot of one bound artifact's own app.
#[cfg(not(target_arch = "wasm32"))]
fn app_instance_slot(catalog: &Catalog, plugin_id: &str, app_id: &str) -> Option<u32> {
    route_slot(catalog, &AppRoute { plugin_id: plugin_id.to_string(), app_id: Some(app_id.to_string()) })
}

/// 🎯️ The `instance` slot any caller must pass to [`ActionAdapter::prepare`]/[`ActionAdapter::invoke`]
/// for `capability_id` — [`plugin_instance_slot`] of the plugin that capability's own catalog entry
/// names. Public because the `action_prepare`/`action_invoke` MCP tools drive the ROOT-owned
/// adapter directly (never [`HeadlessWorkspace::prepare_action`]) and so need the identical
/// derivation: with the bare `0` they used to pass, `prepare`'s leading capability-less
/// `ReadHistory` was routed by [`plugin_for_instance_slot`] to whichever plugin happens to sort
/// first in the catalog, not to the capability's own.
#[cfg(not(target_arch = "wasm32"))]
pub fn capability_instance_slot(catalog: &Catalog, capability_id: &str) -> Option<u32> {
    route_slot(catalog, &resolve_route_for_capability_in(catalog, capability_id).ok()?)
}

/// 🔢️ The inverse of [`route_slot`] — what [`RoutingArtifactChannel::exchange`] decodes an
/// `instance` back into for any `AppCommand` that carries no capability id of its own.
#[cfg(not(target_arch = "wasm32"))]
fn route_for_slot(catalog: &Catalog, instance: u32) -> Option<AppRoute> {
    distinct_routes(catalog).into_iter().nth(instance as usize)
}

/// 🔎️ `capability_id` → the app its own catalog entry names, under the same refusals as
/// [`resolve_plugin_for_capability_in`].
#[cfg(not(target_arch = "wasm32"))]
fn resolve_route_for_capability_in(catalog: &Catalog, capability_id: &str) -> Result<AppRoute, GatewayError> {
    let plugin_id = resolve_plugin_for_capability_in(catalog, capability_id)?;
    let app_id = catalog.get(capability_id).and_then(|capability| match &capability.owner {
        CapabilityOwner::Plugin { app_id, .. } => app_id.clone(),
        _ => None,
    });
    Ok(AppRoute { plugin_id, app_id })
}

/// 🔎️ `capability_id` → its owning plugin id — [`HeadlessWorkspace::resolve_plugin_for_capability`]'s
/// actual body, factored out so [`RoutingArtifactChannel`] (which holds only the `Arc<Catalog>` it
/// needs, not a whole `&HeadlessWorkspace`) can run the identical lookup for a `PureCommand` it is
/// asked to route, without a second copy of this match. An unknown id or one owned by anything other
/// than a plugin (`Os`/`Framework`/`🐚️Shell`/`Gateway`/`Extension`) is a typed error naming exactly
/// which of the two it was — never a guess.
#[cfg(not(target_arch = "wasm32"))]
fn resolve_plugin_for_capability_in(catalog: &Catalog, capability_id: &str) -> Result<String, GatewayError> {
    let capability = catalog.get(capability_id).ok_or_else(|| GatewayError::new(GatewayErrorCode::NotFound, format!("unknown capability: {capability_id}")))?;
    match &capability.owner {
        CapabilityOwner::Plugin { plugin_id, .. } => Ok(plugin_id.clone()),
        owner => Err(GatewayError::new(GatewayErrorCode::PluginUnavailable, format!("capability `{capability_id}` is owned by {}, not a plugin — no artifact channel routes to it", owner.dedup_key())).retryable()),
    }
}

/// 🚧️ `GatewayError` → the `Fault` shape [`ArtifactChannel::exchange`] can actually return —
/// `"capability.not-found"` for a caller-supplied bad id (client-fault, never retryable, matches
/// `GatewayErrorCode::NotFound`'s own `map_fault` arm added alongside this ticket), `"plugin.unavailable"`
/// for everything else (the target plugin genuinely cannot be reached right now — retryable, matches
/// `GatewayErrorCode::PluginUnavailable`).
#[cfg(not(target_arch = "wasm32"))]
fn routing_fault(error: GatewayError) -> Fault {
    let code = match error.code {
        GatewayErrorCode::NotFound => "capability.not-found",
        GatewayErrorCode::Cancelled => ACTIVATION_CANCELLED_FAULT_CODE,
        _ => "plugin.unavailable",
    };
    Fault { code: code.to_string(), message: error.message }
}

/// 🔌️ Shared body of [`HeadlessWorkspace::open_artifact_channel`] and
/// [`RoutingArtifactChannel::exchange`]'s own lazy-open step — both need exactly this (registry entry
/// → committed descriptor → editor app → real `PluginArtifactChannel`) for a bare `plugin_id`,
/// differing only in where `repo_root`/`actor_label` come from.
#[cfg(not(target_arch = "wasm32"))]
fn open_plugin_artifact_channel(source: Option<&PluginComponentSource>, plugin_id: &str, app_id: Option<&str>, actor_label: &str) -> Result<PluginArtifactChannel, GatewayError> {
    open_plugin_artifact_channel_scoped(source, plugin_id, app_id, actor_label, &ActivationScope::detached())
}

/// 🔌️ [`open_plugin_artifact_channel`] under a caller's progress and cancel. `app_id` names the app
/// the guest instance hosts; `None` is the plugin's first editor app.
#[cfg(not(target_arch = "wasm32"))]
fn open_plugin_artifact_channel_scoped(source: Option<&PluginComponentSource>, plugin_id: &str, app_id: Option<&str>, actor_label: &str, scope: &ActivationScope) -> Result<PluginArtifactChannel, GatewayError> {
    scope.enter(ActivationPhase::ResolvingComponent).map_err(activation_fault)?;
    let runtime = shared_plugin_runtime()?;
    let (compiled, descriptor) = match source.ok_or_else(|| {
        GatewayError::new(GatewayErrorCode::Internal, "this workspace is bound to no plugin component source — neither a repo build tree nor an authenticated hub execution target")
    })? {
        PluginComponentSource::Repo(repo_root) => {
            let registry = load_plugin_registry(repo_root)?;
            let entry = find_plugin_entry(&registry, plugin_id)?.clone();
            let descriptor = load_package_descriptor(&entry.owner_root)?;
            let wasm_path = resolve_plugin_wasm_path(repo_root, &entry)?;
            (scoped_compiled_component(runtime.as_ref(), plugin_id, ComponentBytes::File(&wasm_path), scope)?, descriptor)
        }
        PluginComponentSource::Hub(hub) => {
            let (bytes, descriptor) = hub.resolve(plugin_id)?;
            (scoped_compiled_component(runtime.as_ref(), plugin_id, ComponentBytes::Held(&bytes), scope)?, descriptor)
        }
    };
    let app = match app_id {
        Some(app_id) => descriptor.manifest.apps.iter().find(|app| app.id == app_id).ok_or_else(|| GatewayError::new(GatewayErrorCode::NotFound, format!("plugin `{plugin_id}` declares no app `{app_id}`")))?,
        None => descriptor.manifest.apps.iter().find(|app| app.role == semio_framework::AppRole::Editor).ok_or_else(|| GatewayError::new(GatewayErrorCode::NotFound, format!("plugin `{plugin_id}` declares no editor app")))?,
    };
    let app_ref = semio_framework::AppRef { plugin_id: plugin_id.to_string(), app_id: app.id.clone() };
    Ok(PluginArtifactChannel::from_compiled(runtime, compiled, plugin_id.to_string(), descriptor, app_ref, actor_label.to_string()))
}

//#region 🗂️GuestDocumentCodec
/// ⛽️ The ceiling one pure `codec` call runs under. The WIT states the contract these functions
/// honour — no storage, no window, no effect, one throwaway instance per call — so what bounds them
/// is wall time, not effect or frame counts. 60 s is the same order as [`headless_open_budget`],
/// because printing or applying against an 80 KB document pack is work of the same scale as bringing
/// an instance up, and a guest that needs longer is wedged rather than busy.
/// 🧵️ The binding generation this gateway claims for a document backbone. One session opens one
/// binding per instance and never rebinds — a rebind is what a shell does when a window swaps
/// documents, which a headless channel with one bound artifact per plugin cannot do — so the
/// generation is a constant rather than a counter that would imply a history it does not have.
#[cfg(not(target_arch = "wasm32"))]
const DOCUMENT_BACKBONE_BINDING_GENERATION: u64 = 1;

#[cfg(not(target_arch = "wasm32"))]
fn headless_codec_budget() -> semio_framework::kernel::Budget {
    semio_framework::kernel::Budget { fuel: u64::MAX, deadline_ms: 60_000, max_effects: 0, max_patch_bytes: 0, max_frames: 0 }
}

/// 🌐️ The process's tokio I/O reactor, for the hub DOCUMENT SOCKET and nothing else.
///
/// 🐛️ `store::sync`'s native artifact actor dials its document socket with
/// `tokio_tungstenite::connect_async` under a `tokio::time::timeout`
/// (`🏪️store/🔄️sync/🦀️.rs`, `connect_hub`), and `spawn_actor` captures
/// `tokio::runtime::Handle::try_current()` **at the moment `ArtifactHost::open` is awaited**, then
/// `enter()`s it around every turn it polls. A shell binary is inside a tokio runtime when it opens
/// a document; this gateway is not — `semio_framework_os_services::TokioHostRuntime` is the repo's
/// own `WorkerPool`-backed host runtime and carries no tokio reactor despite the name. So the
/// captured handle was `None` and the FIRST socket dial panicked the pool worker with "there is no
/// reactor running, must be called from the context of a Tokio 1.x runtime" (measured live on hub
/// 7681, 2026-09-22, `🗑️generated/m10-write-path-7681-note.txt`).
///
/// 🧭️ Multi-threaded on purpose, and tiny: a current-thread runtime would register the socket but
/// park nobody on its I/O driver, so readiness would never be delivered to a future this crate polls
/// on a worker thread. Two workers are enough for one websocket per open document, and the reactor
/// is process-wide so it outlives any one workspace — a document actor must not lose its driver
/// because the session that opened it went away mid-close.
#[cfg(not(target_arch = "wasm32"))]
fn hub_socket_reactor() -> Result<&'static tokio::runtime::Runtime, GatewayError> {
    static REACTOR: std::sync::OnceLock<Result<tokio::runtime::Runtime, String>> = std::sync::OnceLock::new();
    REACTOR
        .get_or_init(|| tokio::runtime::Builder::new_multi_thread().worker_threads(2).enable_io().enable_time().thread_name("semio-mcp-document-socket").build().map_err(|error| error.to_string()))
        .as_ref()
        .map_err(|error| GatewayError::new(GatewayErrorCode::Internal, format!("building the hub document-socket reactor: {error}")))
}

/// 💓️ Whether a hub document event is a moment an agent session owes the hub a presence beat: a
/// new connection (`Session`) or a live status on it. Everything else leaves the roster as it is.
#[cfg(not(target_arch = "wasm32"))]
pub(crate) fn agent_presence_moment(event: &store::sync::ArtifactEvent) -> bool {
    matches!(event, store::sync::ArtifactEvent::Session { .. } | store::sync::ArtifactEvent::Status(store::sync::ArtifactSyncStatus { remote: store::sync::RemoteState::Live { .. }, .. }))
}

/// 🤖️ The identity-only peer an agent session beats: every app-owned ephemeral absent, and no
/// admitted field claimed, since the hub overwrites label, user, role, color, surface and principal
/// kind with what it authenticated for the socket.
#[cfg(not(target_arch = "wasm32"))]
pub(crate) fn agent_presence_peer(actor: &str) -> store::os_spr::PresencePeer {
    store::os_spr::PresencePeer {
        actor: actor.to_string(),
        connected_at_ms: 0,
        label: None,
        presence_pack: None,
        user_id: None,
        role: None,
        drag_ghost_json: None,
        interaction: None,
        color: None,
        surface: None,
        views: Vec::new(),
        ui: None,
        tool_run: None,
        principal_kind: None,
        active_tool: None,
        history_edit: None,
        typing: Vec::new(),
    }
}

/// 🗂️ One package's own document codec, as the component exports it — the compiled component plus
/// the artifact schema it was registered for.
///
/// 🧭️ `runtime` is the process-wide [`shared_plugin_runtime`] and never a second one: a
/// `wasmtime::Component` belongs to the `Engine` that compiled it, so `compiled` is only
/// instantiable by the runtime that produced it.
#[cfg(not(target_arch = "wasm32"))]
struct GuestCodecRoute {
    dialect: semio_framework::io_schema::ArtifactDialect,
    artifact_schema: String,
    plugin_id: String,
    runtime: Arc<GuestRuntimes>,
    compiled: semio_framework_plugin_host::CompiledHandle,
}

/// 🗂️ Every guest-backed codec this process has registered, in registration order.
///
/// 🧭️ A process-global table exists because [`store::ArtifactCodec`]'s four operations are bare,
/// NON-CAPTURING `fn` pointers — an erasure table, by design, so that a schema-string-keyed caller
/// can print and apply without naming a concrete `P`/`Mutation`. A thunk therefore cannot close over
/// a component, and cannot be told which schema it was registered under either: the signatures carry
/// only bytes. So a thunk resolves its route by asking the components themselves, in order, and
/// taking the first that answers — see [`guest_print_mirror`] for why that is the WIT's own
/// discriminator rather than a guess.
#[cfg(not(target_arch = "wasm32"))]
fn guest_codec_routes() -> &'static Mutex<Vec<Arc<GuestCodecRoute>>> {
    static ROUTES: std::sync::OnceLock<Mutex<Vec<Arc<GuestCodecRoute>>>> = std::sync::OnceLock::new();
    ROUTES.get_or_init(|| Mutex::new(Vec::new()))
}

#[cfg(not(target_arch = "wasm32"))]
fn guest_codec_route_snapshot() -> Vec<Arc<GuestCodecRoute>> {
    guest_codec_routes().lock().unwrap_or_else(std::sync::PoisonError::into_inner).clone()
}

/// 📥️ `(pack, spr) -> (dsl, ops)` through whichever registered component owns this pair.
///
/// 🧭️ **The component IS the discriminator.** `interface codec`'s own contract states it: "a pair
/// the component cannot print back is not a document of this kind". So asking each registered
/// package in turn and taking the first that answers is not a guess at the schema — it is running
/// the exact fence the interface defines, once per candidate. In a real gateway session the
/// candidate list is the packages whose documents this agent has open, which is one or two.
#[cfg(not(target_arch = "wasm32"))]
fn guest_print_mirror<'a>(pack: &'a [u8], spr: &'a [u8]) -> std::pin::Pin<Box<dyn std::future::Future<Output = Result<store::ArtifactTextFiles, store::VcsError>> + Send + 'a>> {
    Box::pin(async move {
        let routes = guest_codec_route_snapshot();
        let mut refusals: Vec<String> = Vec::new();
        for route in &routes {
            match route.runtime.codec_print_mirror(&route.compiled, &route.artifact_schema, pack, spr, &headless_codec_budget()).await {
                Ok(mirror) => return Ok(store::ArtifactTextFiles { dsl: mirror.dsl, ops: mirror.ops }),
                Err(error) => refusals.push(format!("{}/{}: {error}", route.plugin_id, route.artifact_schema)),
            }
        }
        Err(store::VcsError::Deserialize(format!("no registered guest codec prints this pair ({} candidate(s): {})", routes.len(), refusals.join("; "))))
    })
}

/// 🧩️ `(pack, spr, encode_ops_vec) -> (pack, spr, ops text)` through the same route resolution.
/// The ops text is the component's own print of the RESULT pair, never a host re-derivation.
#[cfg(not(target_arch = "wasm32"))]
fn guest_apply_ops_binary<'a>(pack: &'a [u8], spr: &'a [u8], ops: &'a [u8]) -> store::ArtifactCodecApplyFuture<'a> {
    Box::pin(async move {
        let routes = guest_codec_route_snapshot();
        let mut refusals: Vec<String> = Vec::new();
        for route in &routes {
            let budget = headless_codec_budget();
            let applied = match route.runtime.codec_apply_ops(&route.compiled, &route.artifact_schema, pack, spr, ops, &budget).await {
                Ok(applied) => applied,
                Err(error) => {
                    refusals.push(format!("{}/{}: {error}", route.plugin_id, route.artifact_schema));
                    continue;
                }
            };
            let mirror = route
                .runtime
                .codec_print_mirror(&route.compiled, &route.artifact_schema, &applied.pack, &applied.spr, &budget)
                .await
                .map_err(|error| store::VcsError::Serialize(format!("{}/{} applied the batch but cannot print the result: {error}", route.plugin_id, route.artifact_schema)))?;
            return Ok((applied.pack, applied.spr, mirror.ops));
        }
        Err(store::VcsError::Deserialize(format!("no registered guest codec applies this batch ({} candidate(s): {})", routes.len(), refusals.join("; "))))
    })
}

/// 📜️ `(pack, spr, encode_envelopes) -> (pack, spr, ops text)` — the replica fold of a ledger
/// stream through the same route resolution; the ops text is the component's own print of the result.
#[cfg(not(target_arch = "wasm32"))]
fn guest_replay_envelopes<'a>(pack: &'a [u8], spr: &'a [u8], envelopes: &'a [u8]) -> store::ArtifactCodecApplyFuture<'a> {
    Box::pin(async move {
        let routes = guest_codec_route_snapshot();
        let mut refusals: Vec<String> = Vec::new();
        for route in &routes {
            let budget = headless_codec_budget();
            let replayed = match route.runtime.codec_replay_envelopes(&route.compiled, &route.artifact_schema, pack, spr, envelopes, &budget, |_, _| {}, &semio_framework_plugin_host::GuestCallCancellation::default()).await {
                Ok(replayed) => replayed,
                Err(error) => {
                    refusals.push(format!("{}/{}: {error}", route.plugin_id, route.artifact_schema));
                    continue;
                }
            };
            let mirror = route
                .runtime
                .codec_print_mirror(&route.compiled, &route.artifact_schema, &replayed.pack, &replayed.spr, &budget)
                .await
                .map_err(|error| store::VcsError::Serialize(format!("{}/{} replayed the ledger but cannot print the result: {error}", route.plugin_id, route.artifact_schema)))?;
            return Ok((replayed.pack, replayed.spr, mirror.ops));
        }
        Err(store::VcsError::Deserialize(format!("no registered guest codec replays this ledger ({} candidate(s): {})", routes.len(), refusals.join("; "))))
    })
}

/// 🚫️ `interface codec` exports five functions and neither of these is one of them: there is no
/// `compile-dsl` and no `edit-text-from-envelope` in the WIT, because both belong to the FOLDER text
/// lane (`FolderTextStorage`'s `.dsl`/`.ops` writes) and a guest-backed codec exists precisely for a
/// binding that has no folder. A typed refusal naming that is the honest answer; fabricating text
/// here would put bytes in a `.ops` file that no component ever produced.
#[cfg(not(target_arch = "wasm32"))]
fn guest_compile_dsl<'a>(_dsl: &'a str, _ops: &'a str) -> std::pin::Pin<Box<dyn std::future::Future<Output = Result<(store::ArtifactPackFiles, String), store::VcsError>> + Send + 'a>> {
    Box::pin(async move { Err(store::VcsError::Deserialize("a guest-backed document codec has no `compile-dsl`: `interface codec` exports pack-schema-hash, genesis, print-mirror, apply-ops and replay-envelopes only".to_string())) })
}

#[cfg(not(target_arch = "wasm32"))]
fn guest_edit_text_from_envelope<'a>(_envelope: &'a store::os_spr::MutationEnvelope) -> std::pin::Pin<Box<dyn std::future::Future<Output = Result<String, store::VcsError>> + 'a>> {
    Box::pin(async move { Err(store::VcsError::Deserialize("a guest-backed document codec has no per-envelope text printer: `interface codec` prints whole pairs, not single edits".to_string())) })
}

/// 🪶️ Resolves semantic snapshot conversion by its declared schema and exact dialect.
#[cfg(not(target_arch = "wasm32"))]
fn guest_sqlite_route(schema: &str, dialect: &semio_framework::io_schema::ArtifactDialect) -> Result<Arc<GuestCodecRoute>, semio_framework::io_schema::IoError> {
    guest_codec_routes().lock().unwrap_or_else(std::sync::PoisonError::into_inner).iter().find(|route| route.artifact_schema == schema && &route.dialect == dialect).cloned().ok_or_else(|| format!("no guest SQLite provider for {schema} at {}", dialect.to_coordinate()).into())
}

#[cfg(not(target_arch = "wasm32"))]
fn guest_sqlite_export(schema: &str, dialect: &semio_framework::io_schema::ArtifactDialect, payload: &semio_framework::io_schema::IoPayload, control: &mut semio_framework::sqlite_snapshot::SqliteSnapshotControl<'_>) -> semio_framework::io_schema::IoResult<semio_framework::sqlite_snapshot::SqliteDatabase> {
    use semio_framework::{io::{self}, io_schema::{IoError, IoOutcome, IoPayload}, sqlite_snapshot::{self, SnapshotEncoding, SqliteSnapshotPhase}};
    use semio_framework_plugin_host::{sqlite_wire, GuestCallCancellation};
    control.checkpoint(SqliteSnapshotPhase::ProjectSnapshot, 0, 0)?;
    let route = guest_sqlite_route(schema, dialect)?;
    let (encoding, bytes) = match payload { IoPayload::Binary(bytes) => (SnapshotEncoding::Binary, bytes.as_slice()), IoPayload::Text(text) => (SnapshotEncoding::Text, text.as_bytes()) };
    let limits = control.limits();
    let cancel = GuestCallCancellation::default();
    let _reactor = hub_socket_reactor().map_err(|error| IoError::from(error.to_string()))?.enter();
    let result = semio_framework_async::block_on(route.runtime.codec_sqlite_export(&route.compiled, &dialect.to_coordinate(), encoding.as_str(), bytes, limits, &headless_codec_budget(), |_, _| { if control.checkpoint(SqliteSnapshotPhase::ProjectSnapshot, 0, 0).is_err() { cancel.cancel(); } }, &cancel)).map_err(|error| IoError::from(error.to_string()))?;
    let file = match result { sqlite_wire::SnapshotFileResult::Done(file) => file, sqlite_wire::SnapshotFileResult::Rejected(rejection) => return Err(IoError { message: rejection.message, diagnostics: sqlite_wire::decode_diagnostics(&rejection.diagnostics)? }) };
    let mut database = sqlite_snapshot::import_sqlite_database(&file.bytes, limits, &mut |progress| control.checkpoint(progress.phase, progress.completed, progress.total).is_ok()).map_err(|error| IoError::from(error.to_string()))?;
    let (actual, actual_encoding) = io::io_mechanism::take_sqlite_snapshot_metadata(&mut database)?;
    if actual != *dialect || actual_encoding != encoding { return Err("guest SQLite export metadata disagrees with its exact requested snapshot".to_string().into()); }
    Ok(IoOutcome { value: database, diagnostics: sqlite_wire::decode_diagnostics(&file.diagnostics)? })
}

#[cfg(not(target_arch = "wasm32"))]
fn guest_sqlite_import(schema: &str, dialect: &semio_framework::io_schema::ArtifactDialect, mut database: semio_framework::sqlite_snapshot::SqliteDatabase, encoding: semio_framework::sqlite_snapshot::SnapshotEncoding, control: &mut semio_framework::sqlite_snapshot::SqliteSnapshotControl<'_>) -> semio_framework::io_schema::IoResult<semio_framework::io_schema::IoPayload> {
    use semio_framework::{io::{self}, io_schema::{IoError, IoOutcome, IoPayload}, sqlite_snapshot::{self, SqliteSnapshotPhase}};
    use semio_framework_plugin_host::{sqlite_wire, GuestCallCancellation};
    control.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot, 0, 0)?;
    let route = guest_sqlite_route(schema, dialect)?;
    let limits = control.limits();
    io::io_mechanism::attach_sqlite_snapshot_metadata(&mut database, dialect, encoding, control)?;
    let bytes = sqlite_snapshot::export_sqlite_database(&database, limits, &mut |progress| control.checkpoint(progress.phase, progress.completed, progress.total).is_ok()).map_err(|error| IoError::from(error.to_string()))?;
    let cancel = GuestCallCancellation::default();
    let _reactor = hub_socket_reactor().map_err(|error| IoError::from(error.to_string()))?.enter();
    let result = semio_framework_async::block_on(route.runtime.codec_sqlite_import(&route.compiled, &dialect.to_coordinate(), &bytes, limits, &headless_codec_budget(), |_, _| { if control.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot, 0, 0).is_err() { cancel.cancel(); } }, &cancel)).map_err(|error| IoError::from(error.to_string()))?;
    let payload = match result { sqlite_wire::SnapshotPayloadResult::Done(payload) => payload, sqlite_wire::SnapshotPayloadResult::Rejected(rejection) => return Err(IoError { message: rejection.message, diagnostics: sqlite_wire::decode_diagnostics(&rejection.diagnostics)? }) };
    if payload.encoding != encoding.as_str() { return Err("guest SQLite import returned a different native encoding".to_string().into()); }
    let value = match encoding { sqlite_snapshot::SnapshotEncoding::Binary => IoPayload::Binary(payload.bytes), sqlite_snapshot::SnapshotEncoding::Text => IoPayload::Text(String::from_utf8(payload.bytes).map_err(|error| IoError::from(error.to_string()))?) };
    Ok(IoOutcome { value, diagnostics: sqlite_wire::decode_diagnostics(&payload.diagnostics)? })
}

/// 🗂️ Registers `artifact_schema`'s document codec from the component's OWN `codec` export, and
/// answers the pack-schema hash the component itself computed.
///
/// 🪪️ `expected_pack_schema_hash` is the hub's declared hex hash for this document, and it is a
/// CROSS-CHECK, never the source: the hash that goes into the registry is the one
/// `codec.pack-schema-hash` returned from the component bytes the hub authorized and this process
/// verified by SHA-256. Registering the hub's own number would make `finish_connect_hub`'s
/// `local_schema_hash == authority.pack_schema_hash` compare the hub's value with itself, which is
/// not satisfying that check — it is deleting it.
///
/// 🔁️ Idempotent per schema: a second registration of a schema this process already serves is a
/// no-op that still verifies the hash, so re-opening a document never stacks routes.
///
/// 📦️ The generic pack container extension. A guest-backed codec never reaches the folder
/// text lane (see [`guest_compile_dsl`]), which is the only place this is read.
#[cfg(not(target_arch = "wasm32"))]
fn register_guest_document_codec(plugin_id: &str, artifact_schema: &str, dialect: semio_framework::io_schema::ArtifactDialect, component: &[u8], expected_pack_schema_hash: &str) -> Result<[u8; 32], GatewayError> {
    let runtime = shared_plugin_runtime()?;
    let compiled = shared_compiled_component(runtime.as_ref(), plugin_id, component)?;
    let pack_schema_hash = semio_framework_async::block_on(runtime.codec_pack_schema_hash(&compiled, artifact_schema, &headless_codec_budget()))
        .map_err(|error| GatewayError::new(GatewayErrorCode::Internal, format!("`{plugin_id}` could not answer codec.pack-schema-hash for `{artifact_schema}`: {error}")))?;
    let computed = pack_schema_hash.iter().map(|byte| format!("{byte:02x}")).collect::<String>();
    if !expected_pack_schema_hash.is_empty() && computed != expected_pack_schema_hash {
        return Err(GatewayError::new(
            GatewayErrorCode::PreconditionFailed,
            format!("`{plugin_id}`'s own codec hashes `{artifact_schema}` to {computed}, but the hub's document descriptor declares {expected_pack_schema_hash}"),
        ));
    }
    let sqlite_schema = semio_framework_async::block_on(runtime.codec_sqlite_schema(&compiled, &dialect.to_coordinate(), &headless_codec_budget())).map_err(|error| GatewayError::new(GatewayErrorCode::Internal, format!("guest semantic SQLite schema: {error}")))?;
    let mut routes = guest_codec_routes().lock().unwrap_or_else(std::sync::PoisonError::into_inner);
    if let Some(route) = routes.iter().find(|route| route.artifact_schema == artifact_schema && route.dialect == dialect) {
        if route.compiled.package_hash != compiled.package_hash { return Err(GatewayError::new(GatewayErrorCode::PreconditionFailed, "an exact guest snapshot route is already owned by another component")); }
        return Ok(pack_schema_hash);
    }
    let codec = store::ArtifactCodec {
        schema: artifact_schema.to_string(),
        extension: "semio",
        snapshot_sqlite: Some(store::ArtifactSqliteSnapshotCodec { schema: std::borrow::Cow::Owned(sqlite_schema), snapshot_type: None, export: guest_sqlite_export, import: guest_sqlite_import }),
        pack_schema_hash,
        compile_dsl: guest_compile_dsl,
        print_mirror: guest_print_mirror,
        edit_text_from_envelope: guest_edit_text_from_envelope,
        apply_ops_binary: guest_apply_ops_binary,
        replay_envelopes: guest_replay_envelopes,
    };
    let assembly = store::begin_artifact_assembly().map_err(|error| GatewayError::new(GatewayErrorCode::Internal, error.to_string()))?;
    semio_framework::io::commit_artifact_assembly_registry_plan(&assembly, semio_framework::io::ArtifactAssemblyRegistryPlan { document_codecs: vec![codec.clone()], native_snapshots: vec![semio_framework::io::io_mechanism::NativeSnapshotRegistration { dialect: dialect.clone(), codec }], ..Default::default() }).map_err(|error| GatewayError::new(GatewayErrorCode::Internal, format!("registering a guest-backed semantic codec for `{artifact_schema}`: {error}")))?;
    routes.push(Arc::new(GuestCodecRoute { dialect, artifact_schema: artifact_schema.to_string(), plugin_id: plugin_id.to_string(), runtime: Arc::clone(&runtime), compiled }));
    Ok(pack_schema_hash)
}
//#endregion 🗂️GuestDocumentCodec

/// 🧩️ Where a workspace's plugin components come from. A `--folder` workspace builds them itself and
/// reads them off the repo's own `wasm32-wasip2` deliverable tree; a `--hub` workspace has NO repo —
/// its components are the execution targets the Hub authorized, served by the Hub, verified against
/// the Hub's own manifest. One enum rather than an `Option<PathBuf>` that silently means "no plugins
/// at all" for every hub-bound session, which is what made every `action_prepare` from an agent
/// answer `repo root not found` (M8 §5.3, measured live 2026-09-21).
#[cfg(not(target_arch = "wasm32"))]
#[derive(Clone)]
pub enum PluginComponentSource {
    Repo(PathBuf),
    Hub(Arc<HubPluginComponents>),
}

/// 🌎️ Resolves a plugin id to the component bytes and package descriptor the authenticated Hub
/// selected for one of the space's own documents. The descriptor comes from the catalog snapshot the
/// binding already verified (manifest identity, canonical projection, digest); only the component
/// bytes are fetched here, lazily — one plugin at a time, when an open or an action needs it — by the
/// content address the current catalog's lease names, from the persistent execution-target store or
/// the hub ([`remote::HubComponentAssets`]); a republished catalog names other bytes, never a stale hit.
#[cfg(not(target_arch = "wasm32"))]
pub struct HubPluginComponents {
    binding: Arc<HubRemoteBinding>,
    driver: Arc<NativeHubBindingDriver>,
}

#[cfg(not(target_arch = "wasm32"))]
impl HubPluginComponents {
    pub fn new(binding: Arc<HubRemoteBinding>, driver: Arc<NativeHubBindingDriver>) -> Self {
        Self { binding, driver }
    }

    /// 🧩️ The component bytes and descriptor for `plugin_id`, fetched through the document scope the
    /// Hub itself resolved that package for. A plugin no document in this space uses is a typed
    /// refusal naming the plugins the space's own catalog does carry — never a repo-path fallback,
    /// because a hub-bound agent must run exactly the code the hub authorized or none.
    pub fn resolve(&self, plugin_id: &str) -> Result<(Vec<u8>, semio_framework::PackageDescriptor), GatewayError> {
        self.binding.await_settled(remote::HUB_AUTHORITY_SETTLE_WAIT_MS);
        let catalog = self.binding.ready_catalog_snapshot(i64::try_from(now_ms()).unwrap_or(i64::MAX))?;
        let selection = catalog.selections.iter().find(|selection| selection.lease.package.plugin_id == plugin_id).ok_or_else(|| {
            let available: Vec<&str> = catalog.selections.iter().map(|selection| selection.lease.package.plugin_id.as_str()).collect();
            GatewayError::new(
                GatewayErrorCode::NotFound,
                format!("this hub space authorizes no execution target for plugin `{plugin_id}`; its catalog selects {}", if available.is_empty() { "no plugin at all".to_string() } else { available.join(", ") }),
            )
        })?;
        let bytes = self.driver.fetch_execution_target_component(plugin_id, &selection.scope, &selection.lease.component)?;
        Ok((bytes, selection.descriptor.clone()))
    }
}

/// 🗂️ The capability catalog a workspace routes, prepares and searches by. A folder workspace's is the one it opened
/// with; a hub workspace's follows the hub's descriptor authority — recompiled whenever the set of selected package
/// descriptors changes (a package installed, removed or upgraded on the hub), reused while that set is unchanged.
pub struct WorkspaceCatalog {
    hub: Option<Arc<HubRemoteBinding>>,
    compiled: std::sync::RwLock<(String, Arc<Catalog>)>,
}

impl WorkspaceCatalog {
    pub fn fixed(catalog: Arc<Catalog>) -> Self {
        Self { hub: None, compiled: std::sync::RwLock::new((String::new(), catalog)) }
    }

    /// 🌎️ The catalog of `hub`'s live descriptor authority, compiled from its selected packages now.
    pub fn following(hub: Arc<HubRemoteBinding>) -> Result<Self, GatewayError> {
        let snapshot = hub.ready_catalog_snapshot(i64::try_from(now_ms()).unwrap_or(i64::MAX))?;
        let compiled = (selected_package_key(&snapshot), Arc::new(crate::catalog_from_descriptors(snapshot.selections.iter().map(|selection| selection.descriptor.clone()).collect())?));
        Ok(Self { hub: Some(hub), compiled: std::sync::RwLock::new(compiled) })
    }

    /// 🔒️ The catalog of the live authority, or its unavailability while it refreshes or after it was revoked — never a
    /// set the hub no longer selects. What discovery lists.
    pub fn authoritative(&self) -> Result<Arc<Catalog>, GatewayError> {
        let Some(hub) = &self.hub else { return Ok(Arc::clone(&self.compiled.read().unwrap_or_else(std::sync::PoisonError::into_inner).1)) };
        let snapshot = hub.ready_catalog_snapshot(i64::try_from(now_ms()).unwrap_or(i64::MAX))?;
        let key = selected_package_key(&snapshot);
        let cached = {
            let compiled = self.compiled.read().unwrap_or_else(std::sync::PoisonError::into_inner);
            (compiled.0 == key).then(|| Arc::clone(&compiled.1))
        };
        if let Some(catalog) = cached {
            return Ok(catalog);
        }
        let catalog = Arc::new(crate::catalog_from_descriptors(snapshot.selections.iter().map(|selection| selection.descriptor.clone()).collect())?);
        *self.compiled.write().unwrap_or_else(std::sync::PoisonError::into_inner) = (key, Arc::clone(&catalog));
        Ok(catalog)
    }

    /// 🧭️ The catalog a command routes by: the live authority's, or the last compiled one while it refreshes.
    pub fn current(&self) -> Arc<Catalog> {
        self.authoritative().unwrap_or_else(|_| Arc::clone(&self.compiled.read().unwrap_or_else(std::sync::PoisonError::into_inner).1))
    }
}

/// 🔑️ Which package descriptors a catalog snapshot selects, order-free: each plugin with the byte hash of its descriptor.
fn selected_package_key(snapshot: &AuthorizedCatalogSnapshot) -> String {
    let mut packages: Vec<String> = snapshot.selections.iter().map(|selection| format!("{}@{}", selection.lease.package.plugin_id, selection.lease.package.descriptor_byte_sha256)).collect();
    packages.sort_unstable();
    packages.dedup();
    packages.join(",")
}

/// 🚦️ `crate::actions::ArtifactChannel` implementor that picks the plugin from the CALL instead of
/// pinning one for the whole process — replaces the deleted `resolve_default_plugin_id`'s "exactly
/// one plugin or bust" (`📓️w8-capability-routing.md`). A `PureCommand{capability_id,..}` names its
/// plugin directly (`resolve_plugin_for_capability_in`); every other `AppCommand` variant carries no
/// capability id, so it decodes the SAME plugin from `instance` via `plugin_for_instance_slot` —
/// sound only because `HeadlessWorkspace::prepare_action` (the one caller that mints a FRESH
/// `instance`) derives it from `plugin_instance_slot(capability's owner)` up front, never a bare `0`.
/// Opens (and caches) at most one real `PluginArtifactChannel` per [`AppRoute`] — never all up
/// front, never twice for the same app; the cache lock is held only across one `HashMap`
/// lookup/insert, never across a channel's own `exchange` (no lock-ordering hazard against
/// `open_probes`/`action_adapter`'s mutexes, which this struct never touches).
#[cfg(not(target_arch = "wasm32"))]
pub struct RoutingArtifactChannel {
    catalog: Arc<WorkspaceCatalog>,
    components: Option<PluginComponentSource>,
    actor_label: String,
    /// 🗝️ Keyed by the RESOLVED route (`app_id` always `Some`), so a plugin-scope capability and the
    /// first editor app it runs on share one guest instead of splitting its state across two.
    channels: Mutex<HashMap<AppRoute, PluginArtifactChannel>>,
    /// 🧭️ Each plugin's first editor app, learnt when a plugin-scope route first opened it.
    default_apps: Mutex<HashMap<String, String>>,
    /// 🗿️ The owning workspace's own `artifact_id` → binding map, shared by `Arc`. Read INVERSELY
    /// here — plugin id → the artifact this workspace bound to it — so every stamp a command answers
    /// with names the artifact a client can address, not the plugin that happens to host it.
    plugin_artifacts: Arc<Mutex<HashMap<String, PluginArtifactBinding>>>,
    /// 🌎️ The hub's descriptor authority for this session — present exactly when the workspace is hub-bound. Every
    /// edit reads the principal's space role from it before any guest runs ([`hub_edit_refusal`]).
    hub: Option<Arc<HubRemoteBinding>>,
}

#[cfg(not(target_arch = "wasm32"))]
impl RoutingArtifactChannel {
    pub fn new(catalog: Arc<WorkspaceCatalog>, components: Option<PluginComponentSource>, actor_label: String, plugin_artifacts: Arc<Mutex<HashMap<String, PluginArtifactBinding>>>, hub: Option<Arc<HubRemoteBinding>>) -> Self {
        Self { catalog, components, actor_label, channels: Mutex::new(HashMap::new()), default_apps: Mutex::new(HashMap::new()), plugin_artifacts, hub }
    }

    /// 🧭️ `route` with its app named: a plugin-scope route resolves to the plugin's first editor app,
    /// opening that app's channel the first time so the answer comes from the descriptor itself.
    fn resolved_route(&self, route: AppRoute, scope: &ActivationScope) -> Result<AppRoute, Fault> {
        if route.app_id.is_some() {
            return Ok(route);
        }
        if let Some(app_id) = self.default_apps.lock().unwrap_or_else(std::sync::PoisonError::into_inner).get(&route.plugin_id).cloned() {
            return Ok(AppRoute { plugin_id: route.plugin_id, app_id: Some(app_id) });
        }
        let channel = open_plugin_artifact_channel_scoped(self.components.as_ref(), &route.plugin_id, None, &self.actor_label, scope).map_err(routing_fault)?;
        let resolved = AppRoute { plugin_id: route.plugin_id.clone(), app_id: Some(channel.app_ref.app_id.clone()) };
        self.default_apps.lock().unwrap_or_else(std::sync::PoisonError::into_inner).insert(route.plugin_id, channel.app_ref.app_id.clone());
        self.channels.lock().expect("routing channel cache lock poisoned").entry(resolved.clone()).or_insert(channel);
        Ok(resolved)
    }

    /// 🗿️ The artifact `route`'s live session document IS ([`route_session_artifact`]): the hub document of that app
    /// the agent opened or edited last, or the one artifact a folder session bound to it — `None` when there is none, or
    /// two folder artifacts, which no single stamp could name truthfully.
    fn session_artifact_for(&self, route: &AppRoute) -> Option<String> {
        let bound = self.plugin_artifacts.lock().unwrap_or_else(std::sync::PoisonError::into_inner);
        route_session_artifact(
            bound
                .iter()
                .filter(|(_, binding)| binding.plugin_id == route.plugin_id && route.app_id.as_deref().is_none_or(|app_id| binding.app_id == app_id))
                .map(|(artifact_id, binding)| (artifact_id.as_str(), binding.document.is_some(), binding.used)),
        )
        .map(str::to_string)
    }

    /// 📥️ The canonical pair `plugin_id`'s single bound artifact carries, when it has one — a hub
    /// document, whose bytes live on the hub and nowhere a guest could reach on its own. Keyed off
    /// exactly the binding [`Self::session_artifact_for`] names, so a plugin with two bound
    /// artifacts (which no single session document could be) seeds none.
    fn session_document_for(&self, route: &AppRoute) -> Option<(String, Arc<SessionDocumentPair>)> {
        let artifact_id = self.session_artifact_for(route)?;
        let bound = self.plugin_artifacts.lock().unwrap_or_else(std::sync::PoisonError::into_inner);
        let document = bound.get(&artifact_id)?.document.clone()?;
        Some((artifact_id, document))
    }

    /// 🚫️ The refusal a NEW edit on a hub session gets before its guest runs ([`hub_edit_refusal`]); `None` in a
    /// folder workspace and for every command that authors no edit. A commit or rollback of a transaction already in
    /// flight and an undo still run: they only settle or revert local state.
    fn edit_refusal(&self, route: &AppRoute, commands: &[AppCommand]) -> Option<Fault> {
        if !commands.iter().any(|command| matches!(command, AppCommand::PureCommand { .. } | AppCommand::TransactionPrepare { .. } | AppCommand::TransactionRedo { .. })) {
            return None;
        }
        let hub = self.hub.as_ref()?;
        hub.await_settled(remote::HUB_AUTHORITY_SETTLE_WAIT_MS);
        let role = hub.ready_snapshot(i64::try_from(now_ms()).unwrap_or(i64::MAX)).map(|snapshot| snapshot.space.role).map_err(|error| error.message);
        let artifact_id = self.session_artifact_for(route);
        let mut bound = self.plugin_artifacts.lock().unwrap_or_else(std::sync::PoisonError::into_inner);
        let refusal = hub_edit_refusal(role, &route.plugin_id, artifact_id.as_deref().and_then(|artifact_id| bound.get(artifact_id).map(|binding| (artifact_id, binding))));
        if let Some(binding) = artifact_id.as_deref().and_then(|artifact_id| bound.get_mut(artifact_id)).filter(|_| refusal.is_none()) {
            binding.used = hub_link_tick();
        }
        refusal
    }

    /// 📥️ Takes what `route`'s bound hub document actor delivered since the last take and plans it against
    /// the pair the guest was seeded from ([`plan_hub_inbound`]); a new baseline replaces the binding's pair
    /// here, before the guest is (re)loaded from it. `None` for a route with no bound hub document.
    fn take_hub_inbound(&self, route: &AppRoute) -> Result<Option<HubInboundDelivery>, Fault> {
        let Some(artifact_id) = self.session_artifact_for(route) else { return Ok(None) };
        let mut bound = self.plugin_artifacts.lock().unwrap_or_else(std::sync::PoisonError::into_inner);
        let Some(binding) = bound.get_mut(&artifact_id) else { return Ok(None) };
        let Some(seeded) = binding.document.clone() else { return Ok(None) };
        let relay = Arc::clone(&binding.relay);
        let items = relay.take_inbound();
        if items.is_empty() {
            return Ok(None);
        }
        let plan = plan_hub_inbound(items, &seeded)?;
        let reseeded = match plan.reseed {
            Some(pair) => {
                binding.document = Some(Arc::new(pair));
                true
            }
            None => false,
        };
        Ok(Some(HubInboundDelivery { relay, reseeded, backbone: plan.backbone }))
    }

    /// 📥️ Seeds `channel`'s guest for `instance` with the bound hub document and brings it up to what the
    /// document's actor delivered: reseeded first from a new baseline when there is one, loaded, backbone
    /// bound, then every mutation batch after the baseline, oldest first. A batch the guest refuses is the
    /// typed fault it is; the batches it did not reach go back to the relay for the next command.
    fn seed_session_guest(channel: &mut PluginArtifactChannel, instance: u32, artifact_id: &str, document: &SessionDocumentPair, inbound: Option<HubInboundDelivery>) -> Result<(), Fault> {
        if inbound.as_ref().is_some_and(|delivery| delivery.reseeded) {
            channel.reseed_session_document(instance);
        }
        if let Err(fault) = channel.load_session_document(instance, artifact_id, &document.pack, &document.spr).and_then(|()| channel.ensure_document_backbone(instance)) {
            if let Some(delivery) = inbound {
                delivery.restore();
            }
            return Err(fault);
        }
        let Some(delivery) = inbound else { return Ok(()) };
        let mut batches = delivery.backbone.into_iter();
        while let Some(message) = batches.next() {
            if let Err(fault) = channel.receive_document_backbone(instance, message) {
                delivery.relay.restore_inbound(batches.map(HubInbound::Backbone).collect());
                return Err(Fault { code: fault.code, message: format!("the guest refused a batch its hub document delivered: {}", fault.message) });
            }
        }
        Ok(())
    }

    /// 🧵️ Hands `plugin_id`'s bound document actor every backbone message its guest just published.
    /// `ArtifactActorMsg::DocumentBackbone` is the actor's own verified ingress — it decodes the
    /// envelopes, refuses any that name another document, retains them and relays them to the hub as
    /// `ClientFrame::Commands`. Nothing here interprets a byte of them.
    ///
    /// 🚧️ A binding with no document actor is a typed, named fault, never a silent drop: the guest
    /// HAS committed by the time these bytes exist, so "the edit went nowhere" must be something the
    /// agent is told. [`PluginArtifactBinding::backbone_blocked_by`] carries the reason.
    ///
    /// 🔒️ `session_artifact_for` takes the same lock, so it is called BEFORE this one is held —
    /// `std::sync::Mutex` is not reentrant and nesting them deadlocked the very first committed
    /// message (measured 2026-09-22, the test hung past its 60 s report threshold).
    fn relay_backbone_egress(&self, route: &AppRoute, egress: Vec<Vec<u8>>) -> Result<(Arc<HubRelay>, u64), Fault> {
        let plugin_id = route.plugin_id.as_str();
        let artifact_id = self.session_artifact_for(route);
        let binding = {
            let bound = self.plugin_artifacts.lock().unwrap_or_else(std::sync::PoisonError::into_inner);
            artifact_id.and_then(|artifact_id| bound.get(&artifact_id).map(|binding| (artifact_id, binding.backbone.clone(), binding.backbone_blocked_by.clone(), Arc::clone(&binding.relayed), Arc::clone(&binding.relay))))
        };
        let Some((artifact_id, backbone, blocked_by, relayed, relay)) = binding else {
            return Err(Fault {
                code: "channel.not-wired".to_string(),
                message: format!("plugin `{plugin_id}` published {} document-backbone message(s) but this workspace has bound no document to it", egress.len()),
            });
        };
        let Some(backbone) = backbone else {
            return Err(Fault {
                code: "channel.not-wired".to_string(),
                message: format!(
                    "`{artifact_id}` accepted {} committed document-backbone message(s) that cannot reach the hub: {}",
                    egress.len(),
                    blocked_by.unwrap_or_else(|| "this document has no open document actor".to_string())
                ),
            });
        };
        let since = relay.version();
        for message in egress {
            match store::decode_hot_backbone_message_exact(&message) {
                Ok(store::BackboneMessage::Mutations { .. }) => {}
                Ok(store::BackboneMessage::Ack { .. }) => continue,
                Ok(store::BackboneMessage::Genesis { .. } | store::BackboneMessage::Member { .. } | store::BackboneMessage::Retract { .. }) => {
                    return Err(Fault { code: "channel.not-wired".to_string(), message: format!("`{artifact_id}`'s guest published a genesis, member or retraction message on its hot document backbone") });
                }
                Err(error) => return Err(Fault { code: "channel.not-wired".to_string(), message: format!("`{artifact_id}`'s guest published an undecodable document-backbone message: {error}") }),
            }
            backbone
                .send(store::sync::ArtifactActorMsg::DocumentBackbone { message })
                .map_err(|_| Fault { code: "channel.not-wired".to_string(), message: format!("`{artifact_id}`'s document actor mailbox refused a committed document-backbone message") })?;
            relayed.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
        }
        Ok((relay, since))
    }

    fn plugin_id_for(&self, instance: u32, commands: &[AppCommand]) -> Result<String, Fault> {
        self.route_for(instance, commands).map(|route| route.plugin_id)
    }

    /// 💡️ An inference carries no capability id, but it DOES name its own route owner
    /// (the declared row's contributor) — so it routes directly, never through the
    /// `instance` slot encoding `prepare_action` mints for the mutation protocol.
    fn route_for(&self, instance: u32, commands: &[AppCommand]) -> Result<AppRoute, Fault> {
        let catalog = self.catalog.current();
        for command in commands {
            match command {
                AppCommand::PureCommand { capability_id, .. } => return resolve_route_for_capability_in(&catalog, capability_id).map_err(routing_fault),
                AppCommand::Infer(infer) if !infer.plugin_id.is_empty() => return Ok(AppRoute { plugin_id: infer.plugin_id.clone(), app_id: None }),
                _ => {}
            }
        }
        route_for_slot(&catalog, instance).ok_or_else(|| {
            Fault {
                code: "plugin.unavailable".to_string(),
                message: format!(
                    "instance {instance} names no plugin — this workspace's catalog owns {} plugin(s); route a PureCommand for a specific capability on this instance first",
                    distinct_plugin_ids(&catalog).len()
                ),
            }
        })
    }
}

#[cfg(not(target_arch = "wasm32"))]
impl ArtifactChannel for RoutingArtifactChannel {
    /// 🗿️ Re-read on every exchange, never once at open: `artifact_create` binds the artifact
    /// AFTER the channel that seeded it from the plugin's genesis was already opened, so a
    /// stamp taken from an open-time snapshot would name nothing for the very first mutation.
    ///
    /// 📥️ …and the same re-read seeds the guest with the bound document itself when the binding
    /// carries one (a hub document, whose bytes live on the hub and nowhere this guest can
    /// reach). `load_session_document` is idempotent per instance, so a prepare/commit pair does
    /// not reload between its two halves; an `Infer` skips it because the inference lane drives
    /// its own guest on its own actor ordinal, which this document never belongs to.
    ///
    /// 🧵️ …then bind the guest's document backbone, in that order: the guest refuses a load
    /// while bound. Until this runs the guest publishes no backbone effect at all, so a
    /// committed transaction would answer `SUCCEEDED` and reach nobody.
    ///
    /// 🧵️ …and whatever the guest published on its document backbone during that exchange leaves
    /// the process now, on the bound document's own actor mailbox. Drained on BOTH outcomes: a
    /// command that faulted after its guest already committed still owes those envelopes to the
    /// hub, and leaving them in the channel would hand them to the next, unrelated exchange.
    fn exchange(&mut self, instance: u32, commands: Vec<AppCommand>) -> Result<Vec<AppFrame>, Fault> {
        let route = self.resolved_route(self.route_for(instance, &commands)?, &ActivationScope::detached())?;
        let session_artifact_id = self.session_artifact_for(&route);
        if let Some(refusal) = self.edit_refusal(&route, &commands) {
            return Err(refusal);
        }
        let inbound = if carries_hub_inbound(&commands) { self.take_hub_inbound(&route)? } else { None };
        let session_document = self.session_document_for(&route);
        let hub_bound = self.hub.is_some() && session_document.is_some();
        let mut channels = self.channels.lock().expect("routing channel cache lock poisoned");
        if !channels.contains_key(&route) {
            let channel = open_plugin_artifact_channel(self.components.as_ref(), &route.plugin_id, route.app_id.as_deref(), &self.actor_label).map_err(routing_fault)?;
            channels.insert(route.clone(), channel);
        }
        let channel = channels.get_mut(&route).expect("just inserted above");
        channel.bind_session_artifact(session_artifact_id);
        let seeded = match session_document.filter(|_| !matches!(commands.first(), Some(AppCommand::Infer(_)))) {
            Some((artifact_id, document)) => Self::seed_session_guest(channel, instance, &artifact_id, &document, inbound),
            None => Ok(()),
        };
        let frames = seeded.and_then(|()| channel.exchange(instance, commands));
        let egress = channel.drain_backbone_egress();
        drop(channels);
        if egress.is_empty() {
            return if hub_bound { frames.map(commits_with_nothing_relayed) } else { frames };
        }
        let (relay, since) = self.relay_backbone_egress(&route, egress)?;
        let frames = frames?;
        if !frames.iter().any(|frame| matches!(frame, AppFrame::TransactionCommitted { .. })) {
            return Ok(frames);
        }
        let outcome = relay.await_acknowledged(since, HUB_RELAY_ACK_WAIT_MS);
        Ok(frames
            .into_iter()
            .map(|frame| match frame {
                AppFrame::TransactionCommitted { txn_id, edit_id, .. } => AppFrame::TransactionCommitted { txn_id, edit_id, relay: Some(outcome.clone()) },
                other => other,
            })
            .collect())
    }

    /// 🔌️ Everything [`Self::exchange`] would open before its first command, and nothing else: the
    /// plugin's channel (component resolved, read, hashed, compiled), its guest, and — for a bound
    /// hub document — that document loaded and its backbone bound, in the same order.
    fn activate(&mut self, instance: u32, scope: &ActivationScope) -> Result<(), Fault> {
        let route = self.resolved_route(self.route_for(instance, &[])?, scope)?;
        let session_artifact_id = self.session_artifact_for(&route);
        let inbound = self.take_hub_inbound(&route)?;
        let session_document = self.session_document_for(&route);
        let mut channels = self.channels.lock().expect("routing channel cache lock poisoned");
        if !channels.contains_key(&route) {
            let channel = open_plugin_artifact_channel_scoped(self.components.as_ref(), &route.plugin_id, route.app_id.as_deref(), &self.actor_label, scope).map_err(routing_fault)?;
            channels.insert(route.clone(), channel);
        }
        let channel = channels.get_mut(&route).expect("just inserted above");
        channel.bind_session_artifact(session_artifact_id);
        let activated = match (channel.activate(instance, scope), session_document) {
            (Ok(()), Some((artifact_id, document))) => Self::seed_session_guest(channel, instance, &artifact_id, &document, inbound),
            (activated, _) => {
                if let Some(delivery) = inbound {
                    delivery.restore();
                }
                activated
            }
        };
        let egress = channel.drain_backbone_egress();
        drop(channels);
        if !egress.is_empty() {
            self.relay_backbone_egress(&route, egress)?;
        }
        activated
    }
}
