//#region 🚧️TemporaryFixtureRegeneration
/// 🚧️ [TRACE] One-shot fixture regeneration (ticket 26/09/19): rewrites every committed
/// `🔺️diff/🔣️.json` through `NoteDiff`'s own decode→encode so its `f64` slots carry the canonical
/// `5.0` form instead of the stale `5`. Inert unless `SEMIO_REGENERATE_NOTE_DIFF_FIXTURES` is set.
#[semio_framework_async_macros::async_test]
async fn regenerate_committed_diff_fixtures() {
    if std::env::var("SEMIO_REGENERATE_NOTE_DIFF_FIXTURES").is_err() {
        return;
    }
    fn walk(dir: &std::path::Path, out: &mut Vec<std::path::PathBuf>) {
        let Ok(entries) = std::fs::read_dir(dir) else { return };
        for entry in entries.flatten() {
            let path = entry.path();
            if path.is_dir() {
                walk(&path, out);
            } else if path.file_name().is_some_and(|name| name == "🔣️.json")
                && path.parent().is_some_and(|parent| parent.file_name().is_some_and(|name| name == "🔺️diff"))
                // 🚧️ `🪆️subsets/✳️any/🧬️schema/🔺️diff/🔣️.json` is the committed JSON *SCHEMA* for
                // `NoteDiff`, not a fixture instance of one — and `NoteDiff` decodes it leniently
                // (its `title` field swallows the schema's own `"title": "NoteDiff"`), so a
                // regeneration pass that reaches it silently replaces 309 lines of schema with a
                // 17-line diff instance. Only fixtures under `🧫️fixtures/` are regenerable.
                && path.components().any(|component| component.as_os_str().to_string_lossy() == "🧫️fixtures")
            {
                out.push(path);
            }
        }
    }
    let root = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("..").join("..");
    let mut files = Vec::new();
    walk(&root, &mut files);
    files.sort();
    for path in files {
        let text = std::fs::read_to_string(&path).expect("committed diff reads");
        let decoded: crate::NoteDiff = semio_framework_pack_json::from_json_str(&text, semio_framework_pack_json::JsonMemberPolicy::Reject).expect("committed diff decodes");
        let canonical = semio_framework_pack_json::to_json_string(&decoded);
        if serde_json::from_str::<serde_json::Value>(&canonical).expect("canonical parses") != serde_json::from_str::<serde_json::Value>(&text).expect("committed parses") {
            std::fs::write(&path, canonical).expect("committed diff rewrites");
        }
    }
}
